f4f68bdf-2aea-4dc8-93b2-88043700eea8	2026-04-05 13:57:27.265321+00	2026-04-05 13:57:27.265321+00	t	urn:intuitem:risk:library:ecc-1	essential-cybersecurity-controls	NCA	Essential Cybersecurity Controls	The Saudi National Cybersecurity Authority developed the essential cybersecurity controls (ECC – 1: 2018) after conducting a comprehensive study of multiple national and international cybersecurity frameworks and standards. Reference: https://nca.gov.sa/en/legislation?item=191&slug=controls-list	\N	\N	en	t	© NCA	1	intuitem	2024-04-19	f	{}	\N	f	c9563076aedc76677aa08c021e0f1837865dedf3402ac1384172b60e99465d58	{"framework": {"urn": "urn:intuitem:risk:framework:ecc-1", "name": "Essential Cybersecurity Controls", "ref_id": "essential-cybersecurity-controls", "description": "Saudi National Cybersecurity Authority framework for essential cybersecurity controls (ECC)", "requirement_nodes": [{"urn": "urn:intuitem:risk:req_node:ecc-1:1", "name": "Cybersecurity Governance", "depth": 1, "ref_id": "1", "assessable": false}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-1", "name": "Cybersecurity Strategy", "depth": 2, "ref_id": "1-1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1", "description": "To ensure that cybersecurity plans, goals, initiatives and projects are contributing to compliance with related laws and regulations."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-1-1", "depth": 3, "ref_id": "1-1-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-1", "description": "A cybersecurity strategy must be defined, documented and approved. It must be supported by the head of the organization or his/her delegate (referred to in this document as Authorizing Official). The strategy goals must be in-line with related laws and regulations."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-1-2", "depth": 3, "ref_id": "1-1-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-1", "description": "A roadmap must be executed to implement the cybersecurity strategy."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-1-3", "depth": 3, "ref_id": "1-1-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-1", "description": "The cybersecurity strategy must be reviewed periodically according to planned intervals or upon changes to related laws and regulations."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-2", "name": "Cybersecurity Management", "depth": 2, "ref_id": "1-2", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1", "description": "To ensure Authorizing Official's support in implementing and managing cybersecurity programs within the organization as per related laws and regulations"}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-2-1", "depth": 3, "ref_id": "1-2-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-2", "description": "A dedicated cybersecurity function (e.g., division, department) must be established within the organization. This function must be independent from the Information Technology/Information Communication and Technology (IT/ICT) functions (as per the Royal Decree number 37140 dated 14/8/1438H). It is highly recommended that this cybersecurity function reports directly to the head of the organization or his/her delegate while ensuring that this does not result in a conflict of interest."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-2-2", "depth": 3, "ref_id": "1-2-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-2", "description": "The position of cybersecurity function head (e.g., CISO), and related supervisory and critical positions within the function, must be filled with full-time and experienced Saudi cybersecurity professionals."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-2-3", "depth": 3, "ref_id": "1-2-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-2", "description": "A cybersecurity steering committee must be established by the Authorizing Official to ensure the support and implementation of the cybersecurity programs and initiatives within the organization. Committee members, roles and responsibilities, and governance framework must be defined, documented and approved. The committee must include the head of the cybersecurity function as one of its members. It is highly recommended that the committee reports directly to the head of the organization or his/her delegate while ensuring that this does not result in a conflict of interest."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-3", "name": "Cybersecurity Policies and Procedures", "depth": 2, "ref_id": "1-3", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1", "description": "To ensure that cybersecurity requirements are documented, communicated and complied with by the organization as per related laws and regulations, and organizational requirements."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-3-1", "depth": 3, "ref_id": "1-3-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-3", "description": "Cybersecurity policies and procedures must be defined and documented by the cybersecurity function, approved by the Authorizing Official, and disseminated to relevant parties inside and outside the organization."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-3-2", "depth": 3, "ref_id": "1-3-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-3", "description": "The cybersecurity function must ensure that the cybersecurity policies and procedures are implemented."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-3-3", "depth": 3, "ref_id": "1-3-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-3", "description": "The cybersecurity policies and procedures must be supported by technical security standards (e.g., operating systems, databases and firewall technical security standards)."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-3-4", "depth": 3, "ref_id": "1-3-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-3", "description": "The cybersecurity policies and procedures must be reviewed periodically according to planned intervals or upon changes to related laws and regulations. Changes and reviews must be approved and documented."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-4", "name": "Cybersecurity Roles and Responsibilities", "depth": 2, "ref_id": "1-4", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1", "description": "To ensure that roles and responsibilities are defined for all parties participating in implementing the cybersecurity controls within the organization."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-4-1", "depth": 3, "ref_id": "1-4-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-4", "description": "Cybersecurity organizational structure and related roles and responsibilities must be defined, documented, approved, supported and assigned by the Authorizing Official while ensuring that this does not result in a conflict of interest."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-4-2", "depth": 3, "ref_id": "1-4-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-4", "description": "The cybersecurity roles and responsibilities must be reviewed periodically according to planned intervals or upon changes to related laws and regulations."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-5", "name": "Cybersecurity Risk Management", "depth": 2, "ref_id": "1-5", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1", "description": "To ensure managing cybersecurity risks in a methodological approach in order to protect the organization's information and technology assets as per organizational policies and procedures, and related laws and regulations."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-5-1", "depth": 3, "ref_id": "1-5-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-5", "description": "Cybersecurity risk management methodology and procedures must be defined, documented and approved as per confidentiality, integrity and availability considerations of information and technology assets."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-5-2", "depth": 3, "ref_id": "1-5-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-5", "description": "The cybersecurity risk management methodology and procedures must be implemented by the cybersecurity function."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-5-3", "depth": 3, "ref_id": "1-5-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-5", "description": "The cybersecurity risk assessment procedures must be implemented at least in the following cases: 1-5-3-1 Early stages of technology projects. 1-5-3-2 Before making major changes to technology infrastructure. 1-5-3-3 During the planning phase of obtaining third party services. 1-5-3-4 During the planning phase and before going live for new technology services and products."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-5-4", "depth": 3, "ref_id": "1-5-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-5", "description": "The cybersecurity risk management methodology and procedures must be reviewed periodically according to planned intervals or upon changes to related laws and regulations. Changes and reviews must be approved and documented."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-6", "name": "Cybersecurity in Information and Technology Project Management", "depth": 2, "ref_id": "1-6", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1", "description": "To ensure that cybersecurity requirements are included in project management methodology and procedures in order to protect the confidentiality, integrity and availability of information and technology assets as per organization policies and procedures, and related laws and regulations."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-6-1", "depth": 3, "ref_id": "1-6-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-6", "description": "Cybersecurity requirements must be included in project and asset (information/ technology) change management methodology and procedures to identify and manage cybersecurity risks as part of project management lifecycle. The cybersecurity requirements must be a key part of the overall requirements of technology projects."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-6-2", "depth": 3, "ref_id": "1-6-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-6", "description": "The cybersecurity requirements in project and assets (information/technology) change management must include at least the following: 1-6-2-1 Vulnerability assessment and remediation. 1-6-2-2 Conducting a configurations' review, secure configuration and hardening and patching before changes or going live for technology projects."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-6-3", "depth": 3, "ref_id": "1-6-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-6", "description": "The cybersecurity requirements related to software and application development projects must include at least the following: 1-6-3-1 Using secure coding standards. 1-6-3-2 Using trusted and licensed sources for software development tools and libraries. 1-6-3-3 Conducting compliance test for software against the defined organizational cybersecurity requirements. 1-6-3-4 Secure integration between software components. 1-6-3-5 Conducting a configurations' review, secure configuration and hardening and patching before going live for software products."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-6-4", "depth": 3, "ref_id": "1-6-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-6", "description": "The cybersecurity requirements in project management must be reviewed periodically."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-7", "name": "Compliance with Cybersecurity Standards, Laws and Regulations", "depth": 2, "ref_id": "1-7", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1", "description": "To ensure that the organization's cybersecurity program is in compliance with related laws and regulations."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-7-1", "depth": 3, "ref_id": "1-7-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-7", "description": "The organization must comply with related national cybersecurity laws and regulations."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-7-2", "depth": 3, "ref_id": "1-7-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-7", "description": "The organization must comply with any nationally-approved international agreements and commiments related to cybersecurity."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-8", "name": "Periodical Cybersecurity Review and Audit", "depth": 2, "ref_id": "1-8", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1", "description": "To ensure that cybersecurity controls are implemented and in compliance with organizational policies and procedures, as well as related national and international laws, regulations and agreements."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-8-1", "depth": 3, "ref_id": "1-8-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-8", "description": "Cybersecurity reviews must be conducted periodically by the cybersecurity function in the organization to assess the compliance with the cybersecurity controls in the organization."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-8-2", "depth": 3, "ref_id": "1-8-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-8", "description": "Cybersecurity audits and reviews must be conducted by independent parties outside the cybersecurity function (e.g., Internal Audit function) to assess the compliance with the cybersecurity controls in the organization. Audits and reviews must be conducted independently, while ensuring that this does not result in a conflict of interest, as per the Generally Accepted Auditing Standards (GAAS), and related laws and regulations."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-8-3", "depth": 3, "ref_id": "1-8-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-8", "description": "Results from the cybersecurity audits and reviews must be documented and presented to the cybersecurity steering committee and Authorizing Official. Results must include the audit/review scope, observations, recommendations and remediation plans."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-9", "name": "Cybersecurity in Human Resources", "depth": 2, "ref_id": "1-9", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1", "description": "To ensure that cybersecurity risks and requirements related to personnel (employees and contractors) are managed efficiently prior to employment, during employment and after termination/separation as per organizational policies and procedures, and related laws and regulations."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-9-1", "depth": 3, "ref_id": "1-9-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-9", "description": "Personnel cybersecurity requirements (prior to employment, during employment and after termination/separation) must be defined, documented and approved."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-9-2", "depth": 3, "ref_id": "1-9-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-9", "description": "The personnel cybersecurity requirements must be implemented."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-9-3", "depth": 3, "ref_id": "1-9-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-9", "description": "The personnel cybersecurity requirements prior to employment must include at least the following: 1-9-3-1 Inclusion of personnel cybersecurity responsibilities and non-disclosure clauses (covering the cybersecurity requirements during employment and after termination/ separation) in employment contracts. 1-9-3-2 Screening or vetting candidates of cybersecurity and critical/privileged positions."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-9-4", "depth": 3, "ref_id": "1-9-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-9", "description": "The personnel cybersecurity requirements during employment must include at least the following: 1-9-4-1 Cybersecurity awareness (during on-boarding and during employment). 1-9-4-2 Implementation of and compliance with the cybersecurity requirements as per the organizational cybersecurity policies and procedures."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-9-5", "depth": 3, "ref_id": "1-9-5", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-9", "description": "Personnel access to information and technology assets must be reviewed and removed immediately upon termination/separation."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-9-6", "depth": 3, "ref_id": "1-9-6", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-9", "description": "Personnel cybersecurity requirements must be reviewed periodically."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-10", "name": "Cybersecurity Awareness and Training Program", "depth": 2, "ref_id": "1-10", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1", "description": "To ensure that personnel are aware of their cybersecurity responsibilities and have the essential cybersecurity awareness. It is also to ensure that personnel are provided with the required cybersecurity training, skills and credentials needed to accomplish their cybersecurity responsibilities and to protect the organization's information and technology assets."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-10-1", "depth": 3, "ref_id": "1-10-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-10", "description": "A cybersecurity awareness program must be developed and approved. The program must be conducted periodically through multiple channels to strengthen the awareness about cybersecurity, cyber threats and risks, and to build a positive cybersecurity awareness culture."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-10-2", "depth": 3, "ref_id": "1-10-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-10", "description": "The cybersecurity awareness program must be implemented."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-10-3", "depth": 3, "ref_id": "1-10-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-10", "description": "The cybersecurity awareness program must cover the latest cyber threats and how to protect against them, and must include at least the following subjects: 1-10-3-1 Secure handling of email services, especially phishing emails. 1-10-3-2 Secure handling of mobile devices and storage media. 1-10-3-3 Secure Internet browsing. 1-10-3-4 Secure use of social media."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-10-4", "depth": 3, "ref_id": "1-10-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-10", "description": "Essential and customized (i.e., tailored to job functions as it relates to cybersecurity) training and access to professional skillsets must be made available to personnel working directly on tasks related to cybersecurity including: 1-10-4-1 Cybersecurity function's personnel. 1-10-4-2 Personnel working on software/application development. and information and technology assets operations. 1-10-4-3 Executive and supervisory positions."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:1-10-5", "depth": 3, "ref_id": "1-10-5", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:1-10", "description": "The implementation of the cybersecurity awareness program must be reviewed periodically."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2", "name": "Cybersecurity Defense", "depth": 1, "ref_id": "2", "assessable": false}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-1", "name": "Asset Management", "depth": 2, "ref_id": "2-1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2", "description": "To ensure that the organization has an accurate and detailed inventory of information and technology assets in order to support the organization's cybersecurity and operational requirements to maintain the confidentiality, integrity and availability of information and technology assets."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-1-1", "depth": 3, "ref_id": "2-1-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-1", "description": "Cybersecurity requirements for managing information and technology assets must be defined, documented and approved."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-1-2", "depth": 3, "ref_id": "2-1-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-1", "description": "The cybersecurity requirements for managing information and technology assets must be implemented."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-1-3", "depth": 3, "ref_id": "2-1-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-1", "description": "Acceptable use policy of information and technology assets must be defined, documented and approved."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-1-4", "depth": 3, "ref_id": "2-1-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-1", "description": "Acceptable use policy of information and technology assets must be implemented."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-1-5", "depth": 3, "ref_id": "2-1-5", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-1", "description": "Information and technology assets must be classified, labeled and handled as per related law and regulatory requirements."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-1-6", "depth": 3, "ref_id": "2-1-6", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-1", "description": "The cybersecurity requirements for managing information and technology assets must be reviewed periodically."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-2", "name": "Identity and Access Management", "depth": 2, "ref_id": "2-2", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2", "description": "To ensure the secure and restricted logical access to information and technology assets in order to prevent unauthorized access and allow only authorized access for users which are necessary to accomplish assigned tasks."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-2-1", "depth": 3, "ref_id": "2-2-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-2", "description": "Cybersecurity requirements for identity and access management must be defined, documented and approved."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-2-2", "depth": 3, "ref_id": "2-2-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-2", "description": "The cybersecurity requirements for identity and access management must be implemented."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-2-3", "depth": 3, "ref_id": "2-2-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-2", "description": "The cybersecurity requirements for identity and access management must include at least the following 2-2-3-1 User authentication based on username and password. 2-2-3-2 Multi-factor authentication for remote access. 2-2-3-3 User authorization based on identity and access control principles: Need-to-Know and Need-to-Use, Least Privilege and Segregation of Duties. 2-2-3-4 Privileged access management. 2-2-3-5 Periodic review of users' identities and access rights."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-2-4", "depth": 3, "ref_id": "2-2-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-2", "description": "The Implementation of the cybersecurity requirements for identity and access management must be reviewed periodically."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-3", "name": "Information System and Information Processing Facilities Protection", "depth": 2, "ref_id": "2-3", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2", "description": "To ensure the protection of information systems and information processing facilities (including workstations and infrastructures) against cyber risks."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-3-1", "depth": 3, "ref_id": "2-3-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-3", "description": "Cybersecurity requirements for protecting information systems and information processing facilities must be defined, documented and approved."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-3-2", "depth": 3, "ref_id": "2-3-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-3", "description": "The cybersecurity requirements for protecting information systems and information processing facilities must be implemented."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-3-3", "depth": 3, "ref_id": "2-3-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-3", "description": "The cybersecurity requirements for protecting information systems and information processing facilities must include at least the following: 2-3-3-1 Advanced, up-to-date and secure management of malware and virus protection on servers and workstations. 2-3-3-2 Restricted use and secure handling of external storage media. 2-3-3-3 Patch management for information systems, software and devices. 2-3-3-4 Centralized clock synchronization with an accurate and trusted source (e.g., Saudi Standards, Metrology and Quality Organization (SASO))."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-3-4", "depth": 3, "ref_id": "2-3-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-3", "description": "The cybersecurity requirements for protecting information systems and information processing facilities must be reviewed periodically."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-4", "name": "Email Protection", "depth": 2, "ref_id": "2-4", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2", "description": "To ensure the protection of organization's email service from cyber risks."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-4-1", "depth": 3, "ref_id": "2-4-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-4", "description": "Cybersecurity requirements for protecting email service must be defined, documented and approved."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-4-2", "depth": 3, "ref_id": "2-4-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-4", "description": "The cybersecurity requirements for email service must be implemented."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-4-3", "depth": 3, "ref_id": "2-4-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-4", "description": "The cybersecurity requirements for protecting the email service must include at the least the following: 2-4-3-1 Analyzing and filtering email messages (specifically phishing emails and spam) using advanced and up-to-date email protection techniques. 2-4-3-2 Multi-factor authentication for remote and webmail access to email service. 2-4-3-3 Email archiving and backup. 2-4-3-4 Secure management and protection against Advanced Persistent Threats (APT), which normally utilize zero-day viruses and malware. 2-4-3-5 Validation of the organization's email service domains (e.g., using Sender Policy Framework (SPF))."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-4-4", "depth": 3, "ref_id": "2-4-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-4", "description": "The cybersecurity requirements for email service must be reviewed periodically."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-5", "name": "Networks Security Management", "depth": 2, "ref_id": "2-5", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2", "description": "To ensure the protection of organization's network from cyber risks."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-5-1", "depth": 3, "ref_id": "2-5-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-5", "description": "Cybersecurity requirements for network security management must be defined, documented and approved."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-5-2", "depth": 3, "ref_id": "2-5-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-5", "description": "The cybersecurity requirements for network security management must be implemented."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-5-3", "depth": 3, "ref_id": "2-5-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-5", "description": "The cybersecurity requirements for network security management must include at least the following: 2-5-3-1 Logical or physical segregation and segmentation of network segments using firewalls and defense-in-depth principles. 2-5-3-2 Network segregation between production, test and development environments. 2-5-3-3 Secure browsing and Internet connectivity including restrictions on the use of file storage/sharing and remote access websites, and protection against suspicious websites. 2-5-3-4 Wireless network protection using strong authentication and encryption techniques. A comprehensive risk assessment and management exercise must be conducted to assess and manage the cyber risks prior to connecting any wireless networks to the organization's internal network. 2-5-3-5 Management and restrictions on network services, protocols and ports. 2-5-3-6 Intrusion Prevention Systems (IPS). 2-5-3-7 Security of Domain Name Service (DNS). 2-5-3-8 Secure management and protection of Internet browsing channel against Advanced Persistent Threats (APT), which normally utilize zero-day viruses and malware."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-5-4", "depth": 3, "ref_id": "2-5-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-5", "description": "The cybersecurity requirements for network security management must be reviewed periodically."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-6", "name": "Mobile Devices Security", "depth": 2, "ref_id": "2-6", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2", "description": "To ensure the protection of mobile devices (including laptops, smartphones, tablets) from cyber risks and to ensure the secure handling of the organization's information (including sensitive information) while utilizing Bring Your Own Device (BYOD) policy."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-6-1", "depth": 3, "ref_id": "2-6-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-6", "description": "Cybersecurity requirements for mobile devices security and BYOD must be defined, documented and approved."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-6-2", "depth": 3, "ref_id": "2-6-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-6", "description": "The cybersecurity requirements for mobile devices security and BYOD must be implemented."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-6-3", "depth": 3, "ref_id": "2-6-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-6", "description": "The cybersecurity requirements for mobile devices security and BYOD must include at least the following: 2-6-3-1 Separation and encryption of organization's data and information stored on mobile devices and BYODs. 2-6-3-2 Controlled and restricted use based on job requirements. 2-6-3-3 Secure wiping of organization's data and information stored on mobile devices and BYOD in cases of device loss, theft or after termination/separation from the organization. 2-6-3-4 Security awareness for mobile devices users."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-6-4", "depth": 3, "ref_id": "2-6-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-6", "description": "The cybersecurity requirements for mobile devices security and BYOD must be reviewed periodically."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-7", "name": "Data and Information Protection", "depth": 2, "ref_id": "2-7", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2", "description": "To ensure the confidentiality, integrity and availability of organization's data and information as per organizational policies and procedures, and related laws and regulations."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-7-1", "depth": 3, "ref_id": "2-7-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-7", "description": "Cybersecurity requirements for protecting and handling data and information must be defined, documented and approved as per the related laws and regulations."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-7-2", "depth": 3, "ref_id": "2-7-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-7", "description": "The cybersecurity requirements for protecting and handling data and information must be implemented."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-7-3", "depth": 3, "ref_id": "2-7-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-7", "description": "The cybersecurity requirements for protecting and handling data and information must include at least the following: 2-7-3-1 Data and information ownership. 2-7-3-2 Data and information classification and labeling mechanisms. 2-7-3-3 Data and information privacy."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-7-4", "depth": 3, "ref_id": "2-7-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-7", "description": "The cybersecurity requirements for protecting and handling data and information must be reviewed periodically."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-8", "name": "Cryptography", "depth": 2, "ref_id": "2-8", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2", "description": "To ensure the proper and efficient use of cryptography to protect information assets as per organizational policies and procedures, and related laws and regulations."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-8-1", "depth": 3, "ref_id": "2-8-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-8", "description": "Cybersecurity requirements for cryptography must be defined, documented and approved."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-8-2", "depth": 3, "ref_id": "2-8-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-8", "description": "The cybersecurity requirements for cryptography must be implemented."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-8-3", "depth": 3, "ref_id": "2-8-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-8", "description": "The cybersecurity requirements for cryptography must include at least the following: 2-8-3-1 Approved cryptographic solutions standards and its technical and regulatory limitations. 2-8-3-2 Secure management of cryptographic keys during their lifecycles. 2-8-3-3 Encryption of data in-transit and at-rest as per classification and related laws and regulations."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-8-4", "depth": 3, "ref_id": "2-8-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-8", "description": "The cybersecurity requirements for cryptography must be reviewed periodically."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-9", "name": "Backup and Recovery Management", "depth": 2, "ref_id": "2-9", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2", "description": "To ensure the protection of organization's data and information including information systems and software configurations from cyber risks as per organizational policies and procedures, and related laws and regulations."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-9-1", "depth": 3, "ref_id": "2-9-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-9", "description": "Cybersecurity requirements for backup and recovery management must be defined, documented and approved."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-9-2", "depth": 3, "ref_id": "2-9-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-9", "description": "The cybersecurity requirements for backup and recovery management must be implemented."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-9-3", "depth": 3, "ref_id": "2-9-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-9", "description": "The cybersecurity requirements for backup and recovery management must include at least the following: 2-9-3-1 Scope and coverage of backups to cover critical technology and information assets. 2-9-3-2 Ability to perform quick recovery of data and systems after cybersecurity incidents. 2-9-3-3 Periodic tests of backup's recovery effectiveness."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-9-4", "depth": 3, "ref_id": "2-9-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-9", "description": "The cybersecurity requirements for backup and recovery management must be reviewed periodically."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-10", "name": "Vulnerabilities Management", "depth": 2, "ref_id": "2-10", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2", "description": "To ensure timely detection and effective remediation of technical vulnerabilities to prevent or minimize the probability of exploiting these vulnerabilities to launch cyber attacks against the organization."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-10-1", "depth": 3, "ref_id": "2-10-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-10", "description": "Cybersecurity requirements for technical vulnerabilities management must be defined, documented and approved."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-10-2", "depth": 3, "ref_id": "2-10-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-10", "description": "The cybersecurity requirements for technical vulnerabilities management must be implemented."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-10-3", "depth": 3, "ref_id": "2-10-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-10", "description": "The cybersecurity requirements for technical vulnerabilities management must include at least the following: 2-10-3-1 Periodic vulnerabilities assessments. 2-10-3-2 Vulnerabilities classification based on criticality level. 2-10-3-3 Vulnerabilities remediation based on classification and associated risk levels. 2-10-3-4 Security patch management. 2-10-3-5 Subscription with authorized and trusted cybersecurity resources for up-to-date information and notifications on technical vulnerabilities."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-10-4", "depth": 3, "ref_id": "2-10-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-10", "description": "The cybersecurity requirements for technical vulnerabilities management must be reviewed periodically."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-11", "name": "Penetration Testing", "depth": 2, "ref_id": "2-11", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2", "description": "To assess and evaluate the efficiency of the organization's cybersecurity defense capabilities through simulated cyber-attacks to discover unknown weaknesses within the technical infrastructure that may lead to a cyber breach."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-11-1", "depth": 3, "ref_id": "2-11-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-11", "description": "Cybersecurity requirements for penetration testing exercises must be defined, documented and approved."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-11-2", "depth": 3, "ref_id": "2-11-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-11", "description": "The cybersecurity requirements for penetration testing processes must be implemented."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-11-3", "depth": 3, "ref_id": "2-11-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-11", "description": "The cybersecurity requirements for penetration testing processes must include at least the following: 2-11-3-1 Scope of penetration tests which must cover Internet-facing services and its technical components including infrastructure, websites, web applications, mobile apps, email and remote access. 2-11-3-2 Conducting penetration tests periodically."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-11-4", "depth": 3, "ref_id": "2-11-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-11", "description": "Cybersecurity requirements for penetration testing processes must be reviewed periodically."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-12", "name": "Cybersecurity Event Logs and Monitoring Management", "depth": 2, "ref_id": "2-12", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2", "description": "To ensure timely collection, analysis and monitoring of cybersecurity events for early detection of potential cyber-attacks in order to prevent or minimize the negative impacts on the organization's operations."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-12-1", "depth": 3, "ref_id": "2-12-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-12", "description": "Cybersecurity requirements for event logs and monitoring management must be defined, documented and approved."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-12-2", "depth": 3, "ref_id": "2-12-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-12", "description": "The cybersecurity requirements for event logs and monitoring management must be implemented."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-12-3", "depth": 3, "ref_id": "2-12-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-12", "description": "The cybersecurity requirements for event logs and monitoring management must include at least the following: 2-12-3-1 Activation of cybersecurity event logs on critical information assets. 2-12-3-2 Activation of cybersecurity event logs on remote access and privileged user accounts. 2-12-3-3 Identification of required technologies (e.g., SIEM) for cybersecurity event logs collection. 2-12-3-4 Continuous monitoring of cybersecurity events. 2-12-3-5 Retention period for cybersecurity event logs (must be 12 months minimum)."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-12-4", "depth": 3, "ref_id": "2-12-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-12", "description": "The cybersecurity requirements for event logs and monitoring management must be reviewed periodically."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-13", "name": "Cybersecurity Incident and Threat Management", "depth": 2, "ref_id": "2-13", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2", "description": "To ensure timely identification, detection, effective management and handling of cybersecurity incidents and threats to prevent or minimize negative impacts on organization's operation taking into consideration the Royal Decree number 37140, dated 14/8/1438H."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-13-1", "depth": 3, "ref_id": "2-13-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-13", "description": "Requirements for cybersecurity incidents and threat management must be defined, documented and approved."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-13-2", "depth": 3, "ref_id": "2-13-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-13", "description": "The requirements for cybersecurity incidents and threat management must be implemented."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-13-3", "depth": 3, "ref_id": "2-13-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-13", "description": "The requirements for cybersecurity incidents and threat management must include at least the following: 2-13-3-1 Cybersecurity incident response plans and escalation procedures. 2-13-3-2 Cybersecurity incidents classification. 2-13-3-3 Cybersecurity incidents reporting to NCA. 2-13-3-4 Sharing incidents notifications, threat intelligence, breach indicators and reports with NCA. 2-13-3-5 Collecting and handling threat intelligence feeds."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-13-4", "depth": 3, "ref_id": "2-13-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-13", "description": "The requirements for cybersecurity incidents and threat management must be reviewed periodically."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-14", "name": "Physical Security", "depth": 2, "ref_id": "2-14", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2", "description": "To ensure the protection of information and technology assets from unauthorized physical access, loss, theft and damage."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-14-1", "depth": 3, "ref_id": "2-14-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-14", "description": "Cybersecurity requirements for physical protection of information and technology assets must be defined, documented and approved."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-14-2", "depth": 3, "ref_id": "2-14-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-14", "description": "The cybersecurity requirements for physical protection of information and technology assets must be implemented."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-14-3", "depth": 3, "ref_id": "2-14-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-14", "description": "The cybersecurity requirements for physical protection of information and technology assets must include at least the following: 2-14-3-1 Authorized access to sensitive areas within the organization (e.g., data center, disaster recovery center, sensitive information processing facilities, security surveillance center, network cabinets). 2-14-3-2 Facility entry/exit records and CCTV monitoring. 2-14-3-3 Protection of facility entry/exit and surveillance records. 2-14-3-4 Secure destruction and re-use of physical assets that hold classified information (including documents and storage media). 2-14-3-5 Security of devices and equipment inside and outside the organization's facilities."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-14-4", "depth": 3, "ref_id": "2-14-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-14", "description": "The cybersecurity requirements for physical protection of information and technology assets must be reviewed periodically."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-15", "name": "Web Application Security", "depth": 2, "ref_id": "2-15", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2", "description": "To ensure the protection of external web applications against cyber risks."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-15-1", "depth": 3, "ref_id": "2-15-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-15", "description": "Cybersecurity requirements for external web applications must be defined, documented and approved."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-15-2", "depth": 3, "ref_id": "2-15-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-15", "description": "The cybersecurity requirements for external web applications must be implemented."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-15-3", "depth": 3, "ref_id": "2-15-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-15", "description": "The cybersecurity requirements for external web applications must include at least the following: 2-15-3-1 Use of web application firewall. 2-15-3-2 Adoption of the multi-tier architecture principle. 2-15-3-3 Use of secure protocols (e.g., HTTPS). 2-15-3-4 Clarification of the secure usage policy for users. 2-15-3-5 Multi-factor authentication for users' access."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:2-15-4", "depth": 3, "ref_id": "2-15-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:2-15", "description": "The cybersecurity requirements for external web applications must be reviewed periodically."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:3", "name": "Cybersecurity Resilience", "depth": 1, "ref_id": "3", "assessable": false}, {"urn": "urn:intuitem:risk:req_node:ecc-1:3-1", "name": "Cybersecurity Resilience Aspects of Business Continuity Management (BCM)", "depth": 2, "ref_id": "3-1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:3", "description": "To ensure the inclusion of the cybersecurity resiliency requirements within the organization's business continuity management and to remediate and minimize the impacts on systems, information processing facilities and critical e-services from disasters caused by cybersecurity incidents."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:3-1-1", "depth": 3, "ref_id": "3-1-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:3-1", "description": "Cybersecurity requirements for business continuity management must be defined, documented and approved."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:3-1-2", "depth": 3, "ref_id": "3-1-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:3-1", "description": "The cybersecurity requirements for business continuity management must be implemented."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:3-1-3", "depth": 3, "ref_id": "3-1-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:3-1", "description": "The cybersecurity requirements for business continuity management must include at least the following: 3-1-3-1 Ensuring the continuity of cybersecurity systems and procedures. 3-1-3-2 Developing response plans for cybersecurity incidents that may affect the business continuity. 3-1-3-3 Developing disaster recovery plans."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:3-1-4", "depth": 3, "ref_id": "3-1-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:3-1", "description": "The cybersecurity requirements for business continuity management must be reviewed periodically."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:4", "name": "Third-Party and Cloud Computing Cybersecurity", "depth": 1, "ref_id": "4", "assessable": false}, {"urn": "urn:intuitem:risk:req_node:ecc-1:4-1", "name": "Third-Party Cybersecurity", "depth": 2, "ref_id": "4-1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:4", "description": "To ensure the protection of assets against the cybersecurity risks related to third-parties including outsourcing and managed services as per organizational policies and procedures, and related laws and regulations."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:4-1-1", "depth": 3, "ref_id": "4-1-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:4-1", "description": "Cybersecurity requirements for contracts and agreements with third-parties must be identified, documented and approved."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:4-1-2", "depth": 3, "ref_id": "4-1-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:4-1", "description": "The cybersecurity requirements for contracts and agreements with third-parties (e.g., Service Level Agreement (SLA) -which may affect, if impacted, the organization's data or services- must include at least the following: 4-1-2-1 Non-disclosure clauses and secure removal of organization's data by third parties upon end of service. 4-1-2-2 Communication procedures in case of cybersecurity incidents. 4-1-2-3 Requirements for third-parties to comply with related organizational policies and procedures, laws and regulations."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:4-1-3", "depth": 3, "ref_id": "4-1-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:4-1", "description": "The cybersecurity requirements for contracts and agreements with IT outsourcing and managed services third-parties must include at least the following: 4-1-3-1 Conducting a cybersecurity risk assessment to ensure the availability of risk mitigation controls before signing contracts and agreements or upon changes in related regulatory requirements. 4-1-3-2 Cybersecurity managed services centers for monitoring and operations must be completely present inside the Kingdom of Saudi Arabia."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:4-1-4", "depth": 3, "ref_id": "4-1-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:4-1", "description": "The cybersecurity requirements for contracts and agreements with third-parties must be reviewed periodically."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:4-2", "name": "Cloud Computing and Hosting Cybersecurity", "depth": 2, "ref_id": "4-2", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:4", "description": "To ensure the proper and efficient remediation of cyber risks and the implementation of cybersecurity requirements related to hosting and cloud computing as per organizational policies and procedures, and related laws and regulations. It is also to ensure the protection of the organization's information and technology assets hosted on the cloud or processed/managed by third-parties."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:4-2-1", "depth": 3, "ref_id": "4-2-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:4-2", "description": "Cybersecurity requirements related to the use of hosting and cloud computing services must be defined, documented and approved."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:4-2-2", "depth": 3, "ref_id": "4-2-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:4-2", "description": "The cybersecurity requirements related to the use of hosting and cloud computing services must be implemented. In line with related and applicable laws and regulations, and in addition to the applicable ECC controls from main domains (1), (2), (3) and subdomain (4-1), the cybersecurity requirements related to the use of hosting and cloud computing services must include at least the following:"}, {"urn": "urn:intuitem:risk:req_node:ecc-1:4-2-3", "depth": 3, "ref_id": "4-2-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:4-2", "description": "4-2-3-1 Classification of data prior to hosting on cloud or hosting services and returning data (in a usable format) upon service completion. 4-2-3-2 Separation of organization's environments (specifically virtual servers) from other environments hosted at the cloud service provider. 4-2-3-3 Organization's information hosting and storage must be inside the Kingdom of Saudi Arabia."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:4-2-4", "depth": 3, "ref_id": "4-2-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:4-2", "description": "The cybersecurity requirements related to the use of hosting and cloud computing services must be reviewed periodically."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:5", "name": "ICS Cybersecurity", "depth": 1, "ref_id": "5", "assessable": false}, {"urn": "urn:intuitem:risk:req_node:ecc-1:5-1", "name": "Industrial Control Systems (ICS) Protection", "depth": 2, "ref_id": "5-1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:5", "description": "To ensure the appropriate and effective cybersecurity management of Industrial Controls Systems and Operational Technology (ICS/OT) to protect the confidentiality, integrity and availability of the organization's assets against cyber attacks (e.g., unauthorized access, destruction, spying and fraud) in line with the organization's cybersecurity strategy and related and applicable local and international laws and regulations."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:5-1-1", "depth": 3, "ref_id": "5-1-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:5-1", "description": "Cybersecurity requirements related to Industrial Controls Systems and Operational Technology (ICS/OT) must be defined, documented and approved."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:5-1-2", "depth": 3, "ref_id": "5-1-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:5-1", "description": "The cybersecurity requirements related to Industrial Controls Systems and Operational Technology (ICS/OT) must be implemented."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:5-1-3", "depth": 3, "ref_id": "5-1-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:5-1", "description": "In addition to the applicable ECC controls from the main domains (1), (2), (3) and (4), the cybersecurity requirements related to Industrial Controls Systems and Operational Technology (ICS/OT) must include at least the following: 5-1-3-1 Strict physical and virtual segmentation when connecting industrial production networks to other networks within the organization (e.g., corporate network). 5-1-3-2 Strict physical and virtual segmentation when connecting systems and industrial networks with external networks (e.g., Internet, wireless, remote access). 5-1-3-3 Continuous monitoring and activation of cybersecurity event logs on the industrial networks and its connections. 5-1-3-4 Isolation of Safety Instrumental Systems (SIS). 5-1-3-5 Strict limitation on the use of external storage media. 5-1-3-6 Strict limitation on connecting mobile devices to industrial production networks. 5-1-3-7 Periodic review and secure configuration and hardening of industrial, automated, support systems, and devices. 5-1-3-8 Vulnerability management for industrial control systems and operational technology (ICS/OT). 5-1-3-9 Patch management for industrial control systems and operational technology (ICS/OT). 5-1-3-10 Cybersecurity applications management related to the protection of the industrial systems from viruses and malware."}, {"urn": "urn:intuitem:risk:req_node:ecc-1:5-1-4", "depth": 3, "ref_id": "5-1-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:ecc-1:5-1", "description": "The cybersecurity requirements related to Industrial Controls Systems and Operational Technology (ICS/OT) must be reviewed periodically."}]}}	f
32c402e2-1e67-4723-b911-54078a75868e	2026-04-05 13:57:28.246394+00	2026-04-05 13:57:28.246394+00	f	urn:intuitem:risk:library:otcc	OTCC	NCA	Operational Technology Cybersecurity Controls	The NCA publishes the Operational Technology Cybersecurity Controls (OTCC-1:2022). These controls are aligned with related international cybersecurity standards, frameworks, controls, and best practices.\n\nhttps://www.nca.gov.sa/otcc_en.pdf	\N	\N	en	t	Sharing Notice: White\nDocument Classification: Public	1	intuitem	2024-06-19	f	{}	\N	f	6cbefde3a3f809fa50ef24a06ceab3886c42e84a1c2eb6edb0e3814e773ca921	{"framework": {"urn": "urn:intuitem:risk:framework:otcc", "name": "Operational Technology Cybersecurity Controls", "ref_id": "OTCC", "description": "The NCA publishes the Operational Technology Cybersecurity Controls (OTCC-1:2022). These controls are aligned with related international cybersecurity standards, frameworks, controls, and best practices.\\n\\nhttps://www.nca.gov.sa/otcc_en.pdf", "requirement_nodes": [{"urn": "urn:intuitem:risk:req_node:otcc:1", "name": "Cybersecurity Governance", "depth": 1, "ref_id": "1", "assessable": false}, {"urn": "urn:intuitem:risk:req_node:otcc:1-1", "name": "Cybersecurity Policies and Procedures", "depth": 2, "ref_id": "1-1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:1"}, {"urn": "urn:intuitem:risk:req_node:otcc:node4", "name": "Objective", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-1", "description": "To ensure that OT/ICS cybersecurity requirements are documented, communicated, and complied with by the organization as per related laws and regulations, and organizational requirements."}, {"urn": "urn:intuitem:risk:req_node:otcc:node5", "name": "Controls", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-1"}, {"urn": "urn:intuitem:risk:req_node:otcc:1-1-1", "depth": 4, "ref_id": "1-1-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:node5", "description": "With reference to the ECC controls 1-3-1 and 1-3-2, the organization must document, approve, and implement a customized set of cybersecurity policies and procedures for OT/ICS systems or assets.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:1-1-2", "depth": 4, "ref_id": "1-1-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:node5", "description": "With reference to the ECC control 1-3-3, the cybersecurity OT/ICS policies and procedures must be supported by cybersecurity requirements such as vendor recommendations, implementation guidelines, and configuration management guidelines.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:1-1-3", "depth": 4, "ref_id": "1-1-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:node5", "description": "With reference to the ECC control 1-3-4, OT/ICS cybersecurity policies and procedures must be reviewed periodically and/or when there is a change in the risks landscape, organizational structure, and/or process changes.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:1-2", "name": "Cybersecurity Roles and Responsibilities", "depth": 2, "ref_id": "1-2", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:1"}, {"urn": "urn:intuitem:risk:req_node:otcc:node10", "name": "Objective", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-2", "description": "To ensure that roles and responsibilities are defined for all parties participating in implementing the operational technology cybersecurity controls (OTCC) within the organization."}, {"urn": "urn:intuitem:risk:req_node:otcc:node11", "name": "Controls", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-2"}, {"urn": "urn:intuitem:risk:req_node:otcc:1-2-1", "depth": 3, "ref_id": "1-2-1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-2", "description": "In addition to the ECC subdomain 1-4, cybersecurity requirements for Cybersecurity Roles and Responsibilities in OT/ICS must include, at a minimum, the following:"}, {"urn": "urn:intuitem:risk:req_node:otcc:1-2-1-1", "depth": 4, "ref_id": "1-2-1-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-2-1", "description": "Cybersecurity roles and responsibilities (RACI) assignment for all stakeholders of the OT/ICS assets must be defined, documented, communicated and approved by the Authorizing Official while ensuring there is no conflict of interest.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:1-2-1-2", "depth": 4, "ref_id": "1-2-1-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-2-1", "description": "Cybersecurity roles and responsibilities related to OT/ICS assets must be assigned to the cybersecurity function in the organization.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:1-3", "name": "Cybersecurity Risk Management", "depth": 2, "ref_id": "1-3", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:1"}, {"urn": "urn:intuitem:risk:req_node:otcc:node16", "name": "Objective", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-3", "description": "To ensure managing cybersecurity risks in a methodological approach in order to protect the organization's OT/ICS assets as per organizational policies and procedures, and related laws and regulations"}, {"urn": "urn:intuitem:risk:req_node:otcc:node17", "name": "Controls", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-3"}, {"urn": "urn:intuitem:risk:req_node:otcc:1-3-1", "depth": 3, "ref_id": "1-3-1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-3", "description": "In addition to the ECC subdomain 1-5, cybersecurity requirements for cybersecurity risk management in OT/ICS must include, at a minimum, the following:"}, {"urn": "urn:intuitem:risk:req_node:otcc:1-3-1-1", "depth": 4, "ref_id": "1-3-1-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-3-1", "description": "OT/ICS cybersecurity risk management methodology must be included as part of the organization's risk management and safety risk management methodologies.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:1-3-1-2", "depth": 4, "ref_id": "1-3-1-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-3-1", "description": "Cybersecurity risk assessment for OT/ICS assets must be conducted periodically while ensuring to include risks associated with signing contracts and agreements with OT/ICS related third-party organizations and/or upon changes in related regulatory requirements as part of the assessment.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:1-3-1-3", "depth": 4, "ref_id": "1-3-1-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-3-1", "description": "Risk register for OT/ICS cybersecurity risks must be included as part of the organization's risk register.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:1-3-1-4", "depth": 4, "ref_id": "1-3-1-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-3-1", "description": "Appropriate level assignment to facilities which include (OT/ICS) must be conducted based on approved methodology.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:1-3-1-5", "depth": 4, "ref_id": "1-3-1-5", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-3-1", "description": "Include a qualitative analysis of cybersecurity risks within the Process Hazard Analysis (PHA) which is applied with any change in operations and/or procedures in Plants.", "implementation_groups": ["L1"]}, {"urn": "urn:intuitem:risk:req_node:otcc:1-3-1-6", "depth": 4, "ref_id": "1-3-1-6", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-3-1", "description": "In the event that cybersecurity requirements cannot be implemented within the OT/ICS environment, the specific justifications for not applying those requirements must be documented and approved by the respective cybersecurity function and the Authorizing Official.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:1-3-1-7", "depth": 4, "ref_id": "1-3-1-7", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-3-1", "description": "In the event of risk acceptance, alternative cybersecurity controls must be clearly defined, documented, approved by the Authorizing Official, and implemented effectively for a defined period of time while reassessing the risk continuously.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:1-4", "name": "Cybersecurity in Industrial Control System Project Management", "depth": 2, "ref_id": "1-4", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:1"}, {"urn": "urn:intuitem:risk:req_node:otcc:node27", "name": "Objective", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-4", "description": "To ensure that cybersecurity requirements are included in project management methodology and procedures in order to maintain safe operations, confidentiality, integrity, and availability of OT/ICS assets as per organization policies and procedures, and related laws and regulations."}, {"urn": "urn:intuitem:risk:req_node:otcc:node28", "name": "Controls", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-4"}, {"urn": "urn:intuitem:risk:req_node:otcc:1-4-1", "depth": 3, "ref_id": "1-4-1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-4", "description": "In addition to the ECC controls 1-6-2 and 1-6-3, cybersecurity requirements in OT/ICS project management must include, at a minimum, the following:"}, {"urn": "urn:intuitem:risk:req_node:otcc:1-4-1-1", "depth": 4, "ref_id": "1-4-1-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-4-1", "description": "Cybersecurity requirements must be part of OT/ICS project's lifecycle.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:1-4-1-2", "depth": 4, "ref_id": "1-4-1-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-4-1", "description": "Cybersecurity requirements must be included as part of any functional and acceptance testing and evaluation process (such as Factory Acceptance Testing \\"FAT\\", Site Acceptance Testing \\"SAT\\", Commissioning Testing, Change Testing, Integration Testing and Source Code Review).", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:1-4-1-3", "depth": 4, "ref_id": "1-4-1-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-4-1", "description": "Secure-by-design principles must be included as part of security architectural designs for OT/ICS environments.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:1-4-1-4", "depth": 4, "ref_id": "1-4-1-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-4-1", "description": "System development environments including testing environment and integration platforms must be protected.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:1-4-2", "depth": 3, "ref_id": "1-4-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-4", "description": "Cybersecurity requirements within the organization's OT/ICS project management must be reviewed, and their implementation effectiveness is measured and evaluated periodically.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:1-5", "name": "Cybersecurity in Change Management", "depth": 2, "ref_id": "1-5", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:1"}, {"urn": "urn:intuitem:risk:req_node:otcc:node36", "name": "Objective", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-5", "description": "To ensure that cybersecurity requirements are included in change management methodology and procedures in order to maintain safe implementation of change requests in OT/ICS environment by exercising due diligence analysis and control of the changes."}, {"urn": "urn:intuitem:risk:req_node:otcc:node37", "name": "Controls", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-5"}, {"urn": "urn:intuitem:risk:req_node:otcc:1-5-1", "depth": 3, "ref_id": "1-5-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-5", "description": "Cybersecurity requirements within the organization's OT/ICS change management must be defined, documented, and approved. The cybersecurity requirements must be a key part of the overall requirements of OT/ICS change management.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:1-5-2", "depth": 3, "ref_id": "1-5-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-5", "description": "Cybersecurity requirements within the organization's OT/ICS change management lifecycle must be implemented.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:1-5-3", "depth": 3, "ref_id": "1-5-3", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-5", "description": "In addition to the ECC controls 1-6-2 and 1-6-3, cybersecurity requirements in OT/ICS change management must include, at a minimum, the following:"}, {"urn": "urn:intuitem:risk:req_node:otcc:1-5-3-1", "depth": 4, "ref_id": "1-5-3-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-5-3", "description": "Cybersecurity requirements are part of the change management lifecycle.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:1-5-3-2", "depth": 4, "ref_id": "1-5-3-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-5-3", "description": "Changes are validated in a separate environment prior to implementing the changes on the production environment.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:1-5-3-3", "depth": 4, "ref_id": "1-5-3-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-5-3", "description": "In the event that OT/ICS devices are replaced with different, but functionally equivalent devices, whether in design, testing, or operation environments, the cybersecurity of the replacement device must be validated prior to being utilized in operational environment.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:1-5-3-4", "depth": 4, "ref_id": "1-5-3-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-5-3", "description": "Restricted processes for exceptional changes must be implemented.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:1-5-3-5", "depth": 4, "ref_id": "1-5-3-5", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-5-3", "description": "Automated configuration and asset change detection mechanisms must be implemented.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:1-5-4", "depth": 3, "ref_id": "1-5-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-5", "description": "Cybersecurity requirements within the organization's OT/ICS change management requirements must be reviewed, and their implementation effectiveness is measured and evaluated periodically.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:1-6", "name": "Periodical Cybersecurity Review and Audit", "depth": 2, "ref_id": "1-6", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:1"}, {"urn": "urn:intuitem:risk:req_node:otcc:node48", "name": "Objective", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-6", "description": "To ensure that OT/ICS cybersecurity controls are implemented and in compliance with organizational policies and procedures, as well as related national and international laws, regulations and agreements."}, {"urn": "urn:intuitem:risk:req_node:otcc:node49", "name": "Controls", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-6"}, {"urn": "urn:intuitem:risk:req_node:otcc:1-6-1", "depth": 3, "ref_id": "1-6-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-6", "description": "With reference to ECC control 1-8-1, the organization's cybersecurity function must review the implementation of (OTCC-1:2022) controls at least annually.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:1-6-2", "depth": 3, "ref_id": "1-6-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-6", "description": "With reference to ECC control 1-8-2, the implementation of (OTCC-1:2022) controls must be reviewed by independent parties within the organization, outside the cybersecurity function at least once every three years.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:1-7", "name": "Cybersecurity in Human Resources", "depth": 2, "ref_id": "1-7", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:1"}, {"urn": "urn:intuitem:risk:req_node:otcc:node53", "name": "Objective", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-7", "description": "To ensure that cybersecurity risks and requirements related to OT/ICS personnel (employees and third party personnel) are managed efficiently prior to employment, during employment, after termination/separation as per organizational policies and procedures, and related laws and regulations."}, {"urn": "urn:intuitem:risk:req_node:otcc:node54", "name": "Controls", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-7"}, {"urn": "urn:intuitem:risk:req_node:otcc:1-7-1", "depth": 3, "ref_id": "1-7-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-7", "description": "In addition to subcontrols in the ECC control 1-9-3, cybersecurity requirements related to human resources for OT/ICS environment must include, at a minimum, screening or vetting of all personnel (including employees, contractors and subcontractors) who have access or can utilize OT/ICS assets prior to granting them access.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:1-7-2", "depth": 3, "ref_id": "1-7-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-7", "description": "With reference to the ECC control 1-9-6, the cybersecurity requirements for cybersecurity in human resources in OT/ICS must be reviewed, and their implementation effectiveness is measured and evaluated periodically.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:1-8", "name": "Cybersecurity Awareness and Training Program", "depth": 2, "ref_id": "1-8", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:1"}, {"urn": "urn:intuitem:risk:req_node:otcc:node58", "name": "Objective", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-8", "description": "To ensure that personnel are aware of their cybersecurity responsibilities and have the required cybersecurity awareness. It is also to ensure that personnel is provided with the required cybersecurity training, skills, and credentials needed to accomplish their cybersecurity responsibilities and to protect the organization's OT/ICS assets."}, {"urn": "urn:intuitem:risk:req_node:otcc:node59", "name": "Controls", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-8"}, {"urn": "urn:intuitem:risk:req_node:otcc:1-8-1", "depth": 3, "ref_id": "1-8-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-8", "description": "In addition to subcontrols in the ECC control 1-10-3, the cybersecurity awareness program must include a secure and safe interaction with the OT/ICS assets or systems.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:1-8-2", "depth": 3, "ref_id": "1-8-2", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-8", "description": "In addition to subcontrols in the ECC control 1-10-4, cybersecurity requirements in OT/ICS cybersecurity awareness and training program must include, at a minimum, the following:"}, {"urn": "urn:intuitem:risk:req_node:otcc:1-8-2-1", "depth": 4, "ref_id": "1-8-2-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-8-2", "description": "Customized training, qualifications, knowledge, and professional skillsets must be provided to all personnel with access to the OT/ICS assets. The organization is encouraged to utilize the reference material provided in the Saudi Cybersecurity Workforce Framework (SCyWF).", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:1-8-2-2", "depth": 4, "ref_id": "1-8-2-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:1-8-2", "description": "Participation in OT/ICS authorized and/or specialized organizations and groups must be encouraged to stay up-to-date on common cybersecurity practices.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2", "name": "Cybersecurity Defense", "depth": 1, "ref_id": "2", "assessable": false}, {"urn": "urn:intuitem:risk:req_node:otcc:2.1", "name": "Asset Management", "depth": 2, "ref_id": "2.1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2"}, {"urn": "urn:intuitem:risk:req_node:otcc:node66", "name": "Objective", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2.1", "description": "To ensure that the organization has an accurate and detailed inventory of OT/ICS assets in order to support the organization's cybersecurity and operational requirements to maintain the production uptime, safe operations, confidentiality, integrity, and availability of OT/ICS assets."}, {"urn": "urn:intuitem:risk:req_node:otcc:node67", "name": "Controls", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2.1"}, {"urn": "urn:intuitem:risk:req_node:otcc:2-1-1", "depth": 3, "ref_id": "2-1-1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2.1", "description": "In addition to the controls in ECC subdomain 2-1, cybersecurity requirements for asset management in OT/ICS environment must include, at a minimum, the following:"}, {"urn": "urn:intuitem:risk:req_node:otcc:2-1-1-1", "depth": 4, "ref_id": "2-1-1-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-1-1", "description": "OT/ICS assets inventory must be developed in electronic format for all OT/ICS assets, and reviewed periodically.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-1-1-2", "depth": 4, "ref_id": "2-1-1-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-1-1", "description": "Automated solution to collect asset inventory information must be utilized.", "implementation_groups": ["L1"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-1-1-3", "depth": 4, "ref_id": "2-1-1-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-1-1", "description": "OT/ICS asset inventory must be stored securely.", "implementation_groups": ["L1"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-1-1-4", "depth": 4, "ref_id": "2-1-1-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-1-1", "description": "Asset owners for all OT/ICS assets must be identified and involved throughout the relevant asset inventory management lifecycle.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-1-1-5", "depth": 4, "ref_id": "2-1-1-5", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-1-1", "description": "Criticality rating for all assets must be assigned, documented, and approved by asset owners.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-1-2", "depth": 3, "ref_id": "2-1-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2.1", "description": "With reference to the ECC control 2-1-6, the cybersecurity requirements for managing OT/ICS assets must be reviewed, and their implementation effectiveness is measured and evaluated periodically.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-2", "name": "Identity and Access Management", "depth": 2, "ref_id": "2-2", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2"}, {"urn": "urn:intuitem:risk:req_node:otcc:node76", "name": "Objective", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-2", "description": "To ensure secure and restricted logical access to OT/ICS assets in order to prevent unauthorized access and allow only authorized access for users, which are necessary to accomplish assigned tasks."}, {"urn": "urn:intuitem:risk:req_node:otcc:node77", "name": "Controls", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-2"}, {"urn": "urn:intuitem:risk:req_node:otcc:2-2-1", "depth": 3, "ref_id": "2-2-1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-2", "description": "In addition to subcontrols in ECC control 2-2-3, cybersecurity requirements for identity and access management in OT/ICS environment must include, at a minimum, the following:"}, {"urn": "urn:intuitem:risk:req_node:otcc:2-2-1-1", "depth": 4, "ref_id": "2-2-1-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-2-1", "description": "Identity and access management lifecycle for OT/ICS is separated and independent from Information Technology (IT) including centrally managed identity and access management solutions.", "implementation_groups": ["L1"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-2-1-2", "depth": 4, "ref_id": "2-2-1-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-2-1", "description": "Service accounts must be managed securely for OT/ICS services, applications, systems, and devices that are separated and disconnected from interactive users account logins.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-2-1-3", "depth": 4, "ref_id": "2-2-1-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-2-1", "description": "Default credentials for all OT/ICS assets must be changed, disabled, or removed.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-2-1-4", "depth": 4, "ref_id": "2-2-1-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-2-1", "description": "Sessions must be managed securely, including session authenticity, session lockout, and session timeout termination.", "implementation_groups": ["L1"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-2-1-5", "depth": 4, "ref_id": "2-2-1-5", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-2-1", "description": "Automatic disabling/removing of service accounts, programs, or accounts related to (OT/ICS) assets must be prevented, except for monitoring systems.", "implementation_groups": ["L1"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-2-1-6", "depth": 4, "ref_id": "2-2-1-6", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-2-1", "description": "Dual approval and explicit privilege escalation mechanisms for sensitive actions within the OT/ICS environment must be employed.", "implementation_groups": ["L1"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-2-1-7", "depth": 4, "ref_id": "2-2-1-7", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-2-1", "description": "Remote access to the OT/ICS networks must be restricted and exceptionally enabled when necessary and justified. A cybersecurity risk assessment must be conducted prior to granting a remote access and its associated risks are monitored and managed. The granted access must be through trusted multi-factor authenticated and encrypted channel for a defined period of time and with limited access privilege. The remote access session must be monitored and recorded while its time duration and granted user's privilege must be in accordance with the cybersecurity risk assessment.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-2-1-8", "depth": 4, "ref_id": "2-2-1-8", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-2-1", "description": "Secure and complex password standards must be implemented.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-2-1-9", "depth": 4, "ref_id": "2-2-1-9", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-2-1", "description": "Secure mechanisms to store OT/ICS assets' passwords must be used.", "implementation_groups": ["L1"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-2-1-10", "depth": 4, "ref_id": "2-2-1-10", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-2-1", "description": "With reference to the ECC subcontrol 2-2-3-5, users' identities and access rights must be reviewed in response to cybersecurity incidents, personnel roles changes, or whenever there is a change in OT/ICS system architecture.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-2-1-11", "depth": 4, "ref_id": "2-2-1-11", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-2-1", "description": "Access shall be immediately revoked when no longer needed.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-2-2", "depth": 3, "ref_id": "2-2-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-2", "description": "With reference to the ECC control 2-2-4, the cybersecurity requirements for identity and access management in OT/ICS environment must be reviewed, and its implementation effectiveness is measured and evaluated periodically.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-3", "name": "System and Processing Facilities Protection", "depth": 2, "ref_id": "2-3", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2"}, {"urn": "urn:intuitem:risk:req_node:otcc:node92", "name": "Objective", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-3", "description": "To ensure the protection of OT/ICS systems and processing facilities (including workstations, servers and Safety Instrumented Systems \\"SIS\\") against cyber risks."}, {"urn": "urn:intuitem:risk:req_node:otcc:node93", "name": "Controls", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-3"}, {"urn": "urn:intuitem:risk:req_node:otcc:2-3-1", "depth": 3, "ref_id": "2-3-1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-3", "description": "In addition to subcontrols in the ECC control 2-3-3, cybersecurity requirements for system and processing facility protection in OT/ICS environment must include, at a minimum, the following:"}, {"urn": "urn:intuitem:risk:req_node:otcc:2-3-1-1", "depth": 4, "ref_id": "2-3-1-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-3-1", "description": "Advanced, up-to-date protection mechanisms and techniques must be utilized and securely managed to block and protect from malware, Advanced Persistent Threats (APT), malicious files, and activities.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-3-1-2", "depth": 4, "ref_id": "2-3-1-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-3-1", "description": "Periodic security configurations' review and hardening must be conducted in alignment with the vendor implementation guidance or recommendations with respect to cybersecurity and organization's formal change management mechanisms.", "implementation_groups": ["L1"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-3-1-3", "depth": 4, "ref_id": "2-3-1-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-3-1", "description": "Periodic security patches and upgrades must be implemented in alignment with vendor implementation guidance or recommendations with respect to cybersecurity and organization's formal change management mechanisms.", "implementation_groups": ["L1"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-3-1-4", "depth": 4, "ref_id": "2-3-1-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-3-1", "description": "Principles of least privilege and least functionality must be applied.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-3-1-5", "depth": 4, "ref_id": "2-3-1-5", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-3-1", "description": "Safety Instrumented Systems (SIS) controllers must be configured in appropriate modes at all times, which prevent any unauthorized changes, and changes to improper modes are limited to exceptional cases with a specific period of time.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-3-1-6", "depth": 4, "ref_id": "2-3-1-6", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-3-1", "description": "Application whitelisting techniques or other similar techniques must be deployed to limit the applications that are allowed to run in OT/ICS environment.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-3-1-7", "depth": 4, "ref_id": "2-3-1-7", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-3-1", "description": "OT/ICS assets must be managed through dedicated, segmented and hardened Engineering Workstation (EWS) and Human-Machine Interface (HMI) for management purposes and maintenance.", "implementation_groups": ["L1"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-3-1-8", "depth": 4, "ref_id": "2-3-1-8", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-3-1", "description": "External storage media is scanned and analyzed against malware and APT. The scan must be executed in an isolated and secure environment.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-3-1-9", "depth": 4, "ref_id": "2-3-1-9", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-3-1", "description": "Usage of external storage media in the production environment must be restricted unless secure mechanisms for data transfer are developed and properly implemented.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-3-1-10", "depth": 4, "ref_id": "2-3-1-10", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-3-1", "description": "Systems' logs and critical files must be protected from unauthorized access, tampering, illegitimate modification and/or deletion.", "implementation_groups": ["L1"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-3-1-11", "depth": 4, "ref_id": "2-3-1-11", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-3-1", "description": "Unauthorized applications, scripts, tasks, and changes must be detected and analyzed.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-3-1-12", "depth": 4, "ref_id": "2-3-1-12", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-3-1", "description": "New communications sessions and commands execution must be detected and analyzed.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-3-1-13", "depth": 4, "ref_id": "2-3-1-13", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-3-1", "description": "Direct communications between the OT/ICS environment and external hosts must be detected and analyzed.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-3-2", "depth": 3, "ref_id": "2-3-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-3", "description": "With reference to the ECC control 2-3-4, the cybersecurity requirements for system and processing facilities protection in OT/ICS environment must be reviewed, and their implementation effectiveness is measured and evaluated periodically.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-4", "name": "Networks Security Management", "depth": 2, "ref_id": "2-4", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2"}, {"urn": "urn:intuitem:risk:req_node:otcc:node110", "name": "Objective", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-4", "description": "To ensure the protection of the organization's OT/ICS networks from cyber risks."}, {"urn": "urn:intuitem:risk:req_node:otcc:node111", "name": "Controls", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-4"}, {"urn": "urn:intuitem:risk:req_node:otcc:2-4-1", "depth": 3, "ref_id": "2-4-1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-4", "description": "In addition to subcontrols in ECC control 2-5-3, cybersecurity requirements for network security management in OT/ICS environment must cover, at a minimum, the following:"}, {"urn": "urn:intuitem:risk:req_node:otcc:2-4-1-1", "depth": 4, "ref_id": "2-4-1-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-4-1", "description": "OT/ICS environment must be segmented logically or physically from other environments or networks.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-4-1-2", "depth": 4, "ref_id": "2-4-1-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-4-1", "description": "Different zones within the OT/ICS environment must be segmented logically or physically in accordance with the zone's appropriate level that isolates data flows and directs traffic to \\"Choke Points\\".", "implementation_groups": ["L1"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-4-1-3", "depth": 4, "ref_id": "2-4-1-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-4-1", "description": "Safety Instrumented Systems (SIS) must be segmented logically or physically from other OT/ICS networks.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-4-1-4", "depth": 4, "ref_id": "2-4-1-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-4-1", "description": "Wireless technologies (such as Wi-Fi, Bluetooth, cellular, satellite, etc.) must be restricted, and to only be used when the technology meets specific business requirements and is properly secured.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-4-1-5", "depth": 4, "ref_id": "2-4-1-5", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-4-1", "description": "Wireless technologies must be segmented logically or physically from other OT/ICS networks.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-4-1-6", "depth": 4, "ref_id": "2-4-1-6", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-4-1", "description": "Network communications, services, and connection points between different zones must be limited to the minimum to meet operational, maintenance, and safety requirements.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-4-1-7", "depth": 4, "ref_id": "2-4-1-7", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-4-1", "description": "Direct exposure of common remote authentication and access management services on external-facing hosts must be prevented.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-4-1-8", "depth": 4, "ref_id": "2-4-1-8", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-4-1", "description": "Only authorized business-critical services are accessible from the internal OT/ICS networks, and accessibility to services with known vulnerabilities must be limited to the greatest extent possible.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-4-1-9", "depth": 4, "ref_id": "2-4-1-9", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-4-1", "description": "Direct communications between corporate zone and OT/ICS zones must be prevented, and direct all the required connections through dedicated, secured, and hardened jump host/solution in the DMZ zone.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-4-1-10", "depth": 4, "ref_id": "2-4-1-10", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-4-1", "description": "Remote access point in the DMZ zone must not be connected to the OT/ICS networks unless needed, while ensuring that the session is multi-factor authenticated, recorded, and established for a defined period of time only.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-4-1-11", "depth": 4, "ref_id": "2-4-1-11", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-4-1", "description": "Proxies must be employed between the corporate and OT/ICS zones for all machine-to-machine traffic.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-4-1-12", "depth": 4, "ref_id": "2-4-1-12", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-4-1", "description": "Dedicated gateways must be used to segment OT/ICS networks from corporate zone.", "implementation_groups": ["L1"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-4-1-13", "depth": 4, "ref_id": "2-4-1-13", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-4-1", "description": "Dedicated DMZ zone must be used to reside any system that needs services provided by corporate zone.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-4-1-14", "depth": 4, "ref_id": "2-4-1-14", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-4-1", "description": "Strict limitation on enabling/usage of industrial protocols and ports to the minimum to meet operational, maintenance, and safety requirements.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-4-1-15", "depth": 4, "ref_id": "2-4-1-15", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-4-1", "description": "Periodic patches and upgrades for production assets must be certified by respective vendor and tested in a separate environment prior to implementation.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-4-1-16", "depth": 4, "ref_id": "2-4-1-16", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-4-1", "description": "Details related to network architecture and topology, zones, network data flows, connectivity, and interdependencies must be documented, updated, and maintained.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-4-2", "depth": 3, "ref_id": "2-4-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-4", "description": "With reference to the ECC control 2-5-4, the cybersecurity requirements for network security management in OT/ICS environment must be reviewed, and their implementation effectiveness is measured and evaluated periodically.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-5", "name": "Mobile Devices Security", "depth": 2, "ref_id": "2-5", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2"}, {"urn": "urn:intuitem:risk:req_node:otcc:node131", "name": "Objective", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-5", "description": "To ensure the protection of mobile devices (including laptops, handheld configuration devices, network test devices, etc.) from cyber risks and to ensure the secure handling of sensitive data and the organization's information."}, {"urn": "urn:intuitem:risk:req_node:otcc:node132", "name": "Controls", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-5"}, {"urn": "urn:intuitem:risk:req_node:otcc:2-5-1", "depth": 3, "ref_id": "2-5-1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-5", "description": "In addition to subcontrols in the ECC control 2-6-3, cybersecurity requirements for mobile device security in OT/ICS must cover, at a minimum, the following"}, {"urn": "urn:intuitem:risk:req_node:otcc:2-5-1-1", "depth": 4, "ref_id": "2-5-1-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-5-1", "description": "Usage of mobile devices for OT/ICS must be restricted unless specifically required. A cybersecurity risk assessment must be conducted where risks must be defined and managed. A management approval must be granted by respective cybersecurity function for a defined period of time only in alignment with organization's formal access management mechanisms.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-5-1-2", "depth": 4, "ref_id": "2-5-1-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-5-1", "description": "Mobile devices must only be used for their intended purposes and in compliance with cybersecurity requirements of its respective zones prior to being connected to OT/ICS environment, and are hardened and updated with the latest security patches and scanned against malware and APT.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-5-1-3", "depth": 4, "ref_id": "2-5-1-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-5-1", "description": "Limited and approved list of mobile devices must be defined while ensuring that only these mobile devices can be connected to OT/ICS environment.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-5-1-4", "depth": 4, "ref_id": "2-5-1-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-5-1", "description": "Centralized management of mobile devices must be deployed.", "implementation_groups": ["L1"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-5-1-5", "depth": 4, "ref_id": "2-5-1-5", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-5-1", "description": "Encryptions mechanisms must be used for mobile devices authorized to access the OT/ICS assets.", "implementation_groups": ["L1"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-5-2", "depth": 3, "ref_id": "2-5-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-5", "description": "With reference to the ECC control 2-6-4, the cybersecurity requirements for mobile devices security in OT/ICS environment must be reviewed, and their implementation effectiveness is measured and evaluated periodically.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-6", "name": "Data and Information Protection", "depth": 2, "ref_id": "2-6", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2"}, {"urn": "urn:intuitem:risk:req_node:otcc:node141", "name": "Objective", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-6", "description": "To ensure the confidentiality, integrity, and availability of organization's data and information as per organizational policies and procedures, and related laws and regulations."}, {"urn": "urn:intuitem:risk:req_node:otcc:node142", "name": "Controls", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-6"}, {"urn": "urn:intuitem:risk:req_node:otcc:2-6-1", "depth": 3, "ref_id": "2-6-1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-6", "description": "In addition to subcontrols in the ECC control 2-7-3, cybersecurity requirements for data and information protection in OT/ICS must include, at a minimum, the following:"}, {"urn": "urn:intuitem:risk:req_node:otcc:2-6-1-1", "depth": 4, "ref_id": "2-6-1-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-6-1", "description": "Electronic and physical data (at rest and in transit) must be protected at a level consistent with its classification.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-6-1-2", "depth": 4, "ref_id": "2-6-1-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-6-1", "description": "Data Leakage Prevention (DLP) mechanisms must be used to protect the classified data and information.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-6-1-3", "depth": 4, "ref_id": "2-6-1-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-6-1", "description": "Secure wiping mechanisms for configuration details and stored data from OT/ICS assets prior to decommissioning must be implemented.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-6-1-4", "depth": 4, "ref_id": "2-6-1-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-6-1", "description": "Transfer or usage of OT systems' data in any environment other than production environment must be limited, except after applying strict controls for protecting that data.", "implementation_groups": ["L1"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-6-2", "depth": 3, "ref_id": "2-6-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-6", "description": "With reference to the ECC control 2-7-4, the cybersecurity requirements for data and information protection in OT/ICS environment must be reviewed, and their implementation effectiveness is measured and evaluated periodically.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-7", "name": "Cryptography", "depth": 2, "ref_id": "2-7", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2"}, {"urn": "urn:intuitem:risk:req_node:otcc:node150", "name": "Objective", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-7", "description": "To ensure the proper and efficient use of cryptography to protect information assets as per organizational policies and procedures, and related laws and regulations."}, {"urn": "urn:intuitem:risk:req_node:otcc:node151", "name": "Controls", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-7"}, {"urn": "urn:intuitem:risk:req_node:otcc:2-7-1", "depth": 3, "ref_id": "2-7-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-7", "description": "In addition to subcontrols in the ECC control 2-8-3, the organization must ensure that cryptographic technologies used in OT/ICS environment are aligned with the NCA National Cryptographic Standard (NCS1:2020).", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-7-2", "depth": 3, "ref_id": "2-7-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-7", "description": "With reference to the ECC control 2-8-4, the cybersecurity requirements for cryptography in OT/ICS environment must be reviewed, and their implementation effectiveness is measured and evaluated periodically.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-8", "name": "Backup and Recovery Management", "depth": 2, "ref_id": "2-8", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2"}, {"urn": "urn:intuitem:risk:req_node:otcc:node155", "name": "Objective", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-8", "description": "To ensure the protection of organization's data and information, including information systems and software configurations from cyber risks as per organizational policies and procedures, and related laws and regulations."}, {"urn": "urn:intuitem:risk:req_node:otcc:node156", "name": "Controls", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-8"}, {"urn": "urn:intuitem:risk:req_node:otcc:2-8-1", "depth": 3, "ref_id": "2-8-1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-8", "description": "In addition to subcontrols in the ECC control 2-9-3, cybersecurity requirements for backup and recovery management in OT/ICS must include, at a minimum, the following:"}, {"urn": "urn:intuitem:risk:req_node:otcc:2-8-1-1", "depth": 4, "ref_id": "2-8-1-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-8-1", "description": "Backups for all OT/ICS assets must be covered and stored in centralized and offline locations.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-8-1-2", "depth": 4, "ref_id": "2-8-1-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-8-1", "description": "OT/ICS assets' critical configuration files and engineering files must be included in the backup's scope.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-8-1-3", "depth": 4, "ref_id": "2-8-1-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-8-1", "description": "Backups must be performed periodically as per the defined OT/ICS assets classification and their associated risks.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-8-1-4", "depth": 4, "ref_id": "2-8-1-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-8-1", "description": "Access, storage, and transfer of backups and their mediums must be secured to ensure their protection against damage, change, or unauthorized access.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-8-2", "depth": 3, "ref_id": "2-8-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-8", "description": "With reference to the ECC control 2-9-4, the cybersecurity requirements for backup and recovery management in OT/ICS environment must be reviewed, and their implementation effectiveness is measured and evaluated periodically.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-9", "name": "Vulnerabilities Management", "depth": 2, "ref_id": "2-9", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2"}, {"urn": "urn:intuitem:risk:req_node:otcc:node164", "name": "Objective", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-9", "description": "To ensure timely detection and effective remediation of technical vulnerabilities to prevent or minimize the probability of exploiting these vulnerabilities to launch cyber-attacks against the organization."}, {"urn": "urn:intuitem:risk:req_node:otcc:node165", "name": "Controls", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-9"}, {"urn": "urn:intuitem:risk:req_node:otcc:2-9-1", "depth": 3, "ref_id": "2-9-1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-9", "description": "In addition to subcontrols in the ECC control 2-10-3, cybersecurity requirements for vulnerability management in OT/ICS must cover, at a minimum, the following:"}, {"urn": "urn:intuitem:risk:req_node:otcc:2-9-1-1", "depth": 4, "ref_id": "2-9-1-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-9-1", "description": "Scope and activities of vulnerability assessments must be defined for OT/ICS environment as part of organization's formal vulnerability management while ensuring limited or no impact on the production environment.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-9-1-2", "depth": 4, "ref_id": "2-9-1-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-9-1", "description": "With reference to the ECC subcontrol 2-10-3-3, remediation of newly discovered critical vulnerabilities presenting significant risks to the OT/ICS environment must be performed in a timely manner.", "implementation_groups": ["L1"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-9-1-3", "depth": 4, "ref_id": "2-9-1-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-9-1", "description": "With reference to the ECC subcontrol 2-10-3-1, vulnerability assessment for OT/ICS systems must be conducted periodically.\\nLevel 1 : 3 Months / Level 2 : 6 Months / Level 3 : 12 Months", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-9-2", "depth": 3, "ref_id": "2-9-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-9", "description": "With reference to the ECC control 2-10-4, the cybersecurity requirements for vulnerability management in OT/ICS environment must be reviewed, and their implementation effectiveness is measured and evaluated periodically.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-10", "name": "Penetration Testing", "depth": 2, "ref_id": "2-10", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2"}, {"urn": "urn:intuitem:risk:req_node:otcc:node172", "name": "Objective", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-10", "description": "To assess and evaluate the efficiency of the organization's cybersecurity defense capabilities through simulated cyber-attacks to discover unknown weaknesses within the technical infrastructure that may lead to a cyber-breach."}, {"urn": "urn:intuitem:risk:req_node:otcc:node173", "name": "Controls", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-10"}, {"urn": "urn:intuitem:risk:req_node:otcc:2-10-1", "depth": 3, "ref_id": "2-10-1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-10", "description": "In addition to the subcontrols in the ECC control 2-11-3, cybersecurity requirements for penetration testing in OT/ICS must cover, at a minimum, the following:"}, {"urn": "urn:intuitem:risk:req_node:otcc:2-10-1-1", "depth": 4, "ref_id": "2-10-1-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-10-1", "description": "With reference to the ECC subcontrol 2-11-3-1, scope and activities of penetration testing must be defined to ensure the coverage of OT/ICS environment and networks connected to the operational network by qualified team.", "implementation_groups": ["L1"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-10-1-2", "depth": 4, "ref_id": "2-10-1-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-10-1", "description": "With reference to the ECC subcontrol 2-11-3-2, penetration testing must only be conducted with limited or no impact on the production environment, or on an identical separate environment.", "implementation_groups": ["L1"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-10-1-3", "depth": 4, "ref_id": "2-10-1-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-10-1", "description": "With reference to the ECC subcontrol 2-11-3-2, penetration testing for OT/ICS systems must be conducted periodically.\\nLevel 1 : 3 Months / Level 2 : 6 Months / Level 3 : 12 Months", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-10-1-4", "depth": 4, "ref_id": "2-10-1-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-10-1", "description": "Alternative testing methods (such as passive testing mechanisms) must be defined and Implemented to collect relevant information when a potential impact to operational production environment may occur.", "implementation_groups": ["L1"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-10-2", "depth": 3, "ref_id": "2-10-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-10", "description": "With reference to the ECC control 2-11-4, the cybersecurity requirements for penetration testing in OT/ICS environment must be reviewed, and their implementation effectiveness is measured and evaluated periodically.", "implementation_groups": ["L1"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-11", "name": "Cybersecurity Event Logs and Monitoring Management", "depth": 2, "ref_id": "2-11", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2"}, {"urn": "urn:intuitem:risk:req_node:otcc:node181", "name": "Objective", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-11", "description": "To ensure timely collection, analysis, and monitoring of cybersecurity events for early detection of potential cyber-attacks in order to prevent or minimize the negative impacts on the organization's operations."}, {"urn": "urn:intuitem:risk:req_node:otcc:node182", "name": "Controls", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-11"}, {"urn": "urn:intuitem:risk:req_node:otcc:2-11-1", "depth": 3, "ref_id": "2-11-1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-11", "description": "In addition to subcontrols in the ECC control 2-12-3, cybersecurity requirements for cybersecurity event logs and monitoring management in OT/ICS must include, at a minimum, the following:"}, {"urn": "urn:intuitem:risk:req_node:otcc:2-11-1-1", "depth": 4, "ref_id": "2-11-1-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-11-1", "description": "Cybersecurity event logs and audit trails must be activated for all OT/ICS assets.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-11-1-2", "depth": 4, "ref_id": "2-11-1-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-11-1", "description": "Failure attempts in accessing the organization's monitoring systems must be detected and logged.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-11-1-3", "depth": 4, "ref_id": "2-11-1-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-11-1", "description": "Continuous, in-depth cybersecurity log review and monitoring, covering all logs and audit trails must be conducted.", "implementation_groups": ["L1"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-11-1-4", "depth": 4, "ref_id": "2-11-1-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-11-1", "description": "Monitoring, detecting, and analyzing User Behaviors Analytics (UBA) must be performed.", "implementation_groups": ["L1"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-11-1-5", "depth": 4, "ref_id": "2-11-1-5", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-11-1", "description": "Upload or download activities of OT/ICS assets including Safety Instrumented Systems (SIS) must be detected.", "implementation_groups": ["L1"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-11-1-6", "depth": 4, "ref_id": "2-11-1-6", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-11-1", "description": "All remote access sessions must be monitored.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-11-1-7", "depth": 4, "ref_id": "2-11-1-7", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-11-1", "description": "Malicious events must be detected and analyzed.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-11-1-8", "depth": 4, "ref_id": "2-11-1-8", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-11-1", "description": "Logging and monitoring of new alerts when new or unauthorized devices are connected to the OT/ICS networks must be performed.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-11-1-9", "depth": 4, "ref_id": "2-11-1-9", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-11-1", "description": "OT/ICS Threat Intelligence must be used and incorporated to regularly tune and refresh alerts of Security Information and Event Management (SIEM) technologies.", "implementation_groups": ["L1"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-11-1-10", "depth": 4, "ref_id": "2-11-1-10", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-11-1", "description": "All access control points between the network security boundaries and external connections must be monitored.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-11-2", "depth": 3, "ref_id": "2-11-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-11", "description": "With reference to the ECC control 2-12-4, the cybersecurity requirements for cybersecurity event logs and monitoring management in OT/ICS environment must be reviewed, and their implementation effectiveness is measured and evaluated periodically.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-12", "name": "Cybersecurity Incident and Threat Management", "depth": 2, "ref_id": "2-12", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2"}, {"urn": "urn:intuitem:risk:req_node:otcc:node196", "name": "Objective", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-12", "description": "To ensure timely identification, detection, effective management, and handling of cybersecurity incidents and threats to prevent or minimize negative impacts on organization's OT/ICS operation."}, {"urn": "urn:intuitem:risk:req_node:otcc:node197", "name": "Controls", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-12"}, {"urn": "urn:intuitem:risk:req_node:otcc:2-12-1", "depth": 3, "ref_id": "2-12-1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-12", "description": "In addition to subcontrols in the ECC Control 2-13-3, cybersecurity requirements for cybersecurity incident and threat management in OT/ICS must include, at a minimum, the following:"}, {"urn": "urn:intuitem:risk:req_node:otcc:2-12-1-1", "depth": 4, "ref_id": "2-12-1-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-12-1", "description": "OT/ICS cybersecurity incident response plans must be integrated and aligned with organizational plans and its procedures such as IT incident response plans, crisis management, and Business Continuity Plan (BCP).", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-12-1-2", "depth": 4, "ref_id": "2-12-1-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-12-1", "description": "Formal incident response and root cause analysis for any detected cybersecurity incidents must be conducted.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-12-1-3", "depth": 4, "ref_id": "2-12-1-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-12-1", "description": "Sequence of incident response activities necessary to restore normal operations must be defined.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-12-1-4", "depth": 4, "ref_id": "2-12-1-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-12-1", "description": "Incident communications plan must be established.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-12-1-5", "depth": 4, "ref_id": "2-12-1-5", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-12-1", "description": "OT/ICS including Safety Instrumented Systems (SIS) recovery procedures must be included in the incident response, system recovery plans, and business continuity plans.", "implementation_groups": ["L1"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-12-1-6", "depth": 4, "ref_id": "2-12-1-6", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-12-1", "description": "Trainings and skillsets for the organization's personnel (including employees, contractors and subcontractors) to respond to OT/ICS cybersecurity incidents must be provided.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-12-1-7", "depth": 4, "ref_id": "2-12-1-7", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-12-1", "description": "Cybersecurity incident response capabilities, readiness, and plan must be periodically tested by performing cyber-attack simulations exercises.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-12-1-8", "depth": 4, "ref_id": "2-12-1-8", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-12-1", "description": "Threat Intelligence information must be used to identify Tactics, Techniques, and Procedures (TTPs) of activity groups targeting OT/ICS systems.", "implementation_groups": ["L1"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-12-2", "depth": 3, "ref_id": "2-12-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-12", "description": "With reference to the ECC control 2-13-4, the cybersecurity requirements for cybersecurity incident and threat management in OT/ICS environment must be reviewed, and their implementation effectiveness is measured and evaluated periodically.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-13", "name": "Physical Security", "depth": 2, "ref_id": "2-13", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2"}, {"urn": "urn:intuitem:risk:req_node:otcc:node209", "name": "Objective", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-13", "description": "To ensure the protection of OT/ICS assets from unauthorized physical access, loss, theft, and damage."}, {"urn": "urn:intuitem:risk:req_node:otcc:2-13-1", "depth": 3, "ref_id": "2-13-1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-13", "description": "In addition to subcontrols in the ECC Control 2-14-3, cybersecurity requirements for physical security in OT/ICS environment must include, at a minimum, the following:"}, {"urn": "urn:intuitem:risk:req_node:otcc:2-13-1-1", "depth": 4, "ref_id": "2-13-1-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-13-1", "description": "List of personnel with authorized access to facilities and sensitive locations where OT/ICS assets reside must be maintained.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-13-1-2", "depth": 4, "ref_id": "2-13-1-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-13-1", "description": "Real-time physical intrusion detection alarms and surveillance equipment, and proper mechanisms must be implemented to recognize potential intrusions and apply the approved response actions.", "implementation_groups": ["L1"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-13-1-3", "depth": 4, "ref_id": "2-13-1-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-13-1", "description": "Physical access points and perimeter to sensitive OT/ICS areas shall be protected and ensure continuous monitoring.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-13-1-4", "depth": 4, "ref_id": "2-13-1-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-13-1", "description": "Safeguards, such as locks on cabinets containing control systems or sensitive assets related to OT/ICS, must be utilized to prevent unauthorized access to devices that could provide a mechanism to compromise the OT/ICS assets.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-13-1-5", "depth": 4, "ref_id": "2-13-1-5", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-13-1", "description": "Strict limitation must be enforced on the physical access to all OT/ICS assets, including Safety Instrumented Systems (SIS).", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-13-1-6", "depth": 4, "ref_id": "2-13-1-6", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-13-1", "description": "Visitor access records to restricted locations where OT/ICS reside must be maintained.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-13-1-7", "depth": 4, "ref_id": "2-13-1-7", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-13-1", "description": "Work being performed by contractor or vendor personnel must be monitored.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-13-1-8", "depth": 4, "ref_id": "2-13-1-8", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-13-1", "description": "Trainings and skillsets for the organizational security guards must be provided in line with roles and responsibilities with respect to OT/ICS physical security.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-13-1-9", "depth": 4, "ref_id": "2-13-1-9", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-13-1", "description": "Physical security capabilities and readiness must be periodically tested by performing simulation exercises (such as social engineering).", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:2-13-2", "depth": 3, "ref_id": "2-13-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:2-13", "description": "With reference to the ECC control 2-14-4, the cybersecurity requirements for physical security in OT/ICS environment must be reviewed, and their implementation effectiveness is measured and evaluated periodically.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:3", "name": "Cybersecurity Resilience", "depth": 1, "ref_id": "3", "assessable": false}, {"urn": "urn:intuitem:risk:req_node:otcc:3-1", "name": "Cybersecurity Resilience Aspects of Business Continuity Management (BCM)", "depth": 2, "ref_id": "3-1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:3"}, {"urn": "urn:intuitem:risk:req_node:otcc:node223", "name": "Objective", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:3-1", "description": "To ensure the inclusion of the cybersecurity resiliency requirements within the organization's business continuity management and to remediate and minimize the impacts on OT/ICS environment from disasters caused by cybersecurity incidents."}, {"urn": "urn:intuitem:risk:req_node:otcc:node224", "name": "Controls", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:3-1"}, {"urn": "urn:intuitem:risk:req_node:otcc:3-1-1", "depth": 3, "ref_id": "3-1-1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:3-1", "description": "In addition to subcontrols in the ECC control 3-1-3, cybersecurity requirements for cybersecurity resilience aspects of business continuity management in OT/ICS must include, at a minimum, the following:"}, {"urn": "urn:intuitem:risk:req_node:otcc:3-1-1-1", "depth": 4, "ref_id": "3-1-1-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:3-1-1", "description": "Activities necessary to sustain minimum operations of the OT/ICS systems must be defined.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:3-1-1-2", "depth": 4, "ref_id": "3-1-1-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:3-1-1", "description": "Redundant OT/ICS networks, connections, and devices must be implemented in accordance to the periodic cybersecurity risk assessment.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:3-1-1-3", "depth": 4, "ref_id": "3-1-1-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:3-1-1", "description": "OT/ICS cybersecurity requirements must be incorporated into the Business Continuity Plan (BCP), Business Impact Analysis (BIA), Recovery Time Objectives (RTO), and Recovery Point Objectives (RPO).", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:3-1-1-4", "depth": 4, "ref_id": "3-1-1-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:3-1-1", "description": "OT/ICS cybersecurity requirements must be incorporated into the Disaster Recovery Plan (DRP) including cybersecurity-related disaster scenarios, system failure handling procedures, and operational continuity management procedures.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:3-1-1-5", "depth": 4, "ref_id": "3-1-1-5", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:3-1-1", "description": "In the event of a system failure due to a cybersecurity incident, OT/ICS assets or systems must operate on an acceptable safe mode to achieve a continuous operation.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:3-1-1-6", "depth": 4, "ref_id": "3-1-1-6", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:3-1-1", "description": "Periodic testing and simulation exercises (e.g. tabletop exercises \\"TTX\\") must be conducted to test the effectiveness of OT/ICS related DRP and BCP and complete incident root cause analysis.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:3-1-2", "depth": 3, "ref_id": "3-1-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:3-1", "description": "With reference to the ECC control 3-1-4, the cybersecurity requirements for cybersecurity resilience aspects of business continuity management in OT/ICS environment must be reviewed, and their implementation effectiveness is measured and evaluated periodically.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:4", "name": "Third-Party Cybersecurity", "depth": 1, "ref_id": "4", "assessable": false}, {"urn": "urn:intuitem:risk:req_node:otcc:4-1", "name": "Third-Party Cybersecurity", "depth": 2, "ref_id": "4-1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:4"}, {"urn": "urn:intuitem:risk:req_node:otcc:node235", "name": "Objective", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:4-1", "description": "To ensure the protection of organizational assets against the cybersecurity risks related to third-parties, including manufactures of OT/ICS-related hardware and software, vendors of OT/ICS products and suppliers of OT/ICS-related services as per organizational policies and procedures, and related laws and regulations."}, {"urn": "urn:intuitem:risk:req_node:otcc:node236", "name": "Controls", "depth": 3, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:4-1"}, {"urn": "urn:intuitem:risk:req_node:otcc:4-1-1", "depth": 3, "ref_id": "4-1-1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:otcc:4-1", "description": "In addition to the ECC subcontrols within controls 4-1-2 and 4-1-3, cybersecurity requirements for third-party cybersecurity in OT/ICS must include, at a minimum, the following:"}, {"urn": "urn:intuitem:risk:req_node:otcc:4-1-1-1", "depth": 4, "ref_id": "4-1-1-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:4-1-1", "description": "Cybersecurity requirements are included during procurement lifecycle for OT/ICS products and services.", "implementation_groups": ["L1", "L2", "L3"]}, {"urn": "urn:intuitem:risk:req_node:otcc:4-1-1-2", "depth": 4, "ref_id": "4-1-1-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:4-1-1", "description": "Cybersecurity requirements for third-party evaluation, selection, and information sharing must be defined.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:4-1-1-3", "depth": 4, "ref_id": "4-1-1-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:4-1-1", "description": "Third-party contractors and vendors must use formal and documented Secure Development Life Cycle (SDLC) practices for systems and components designed or deployed in OT/ICS environment.", "implementation_groups": ["L1", "L2"]}, {"urn": "urn:intuitem:risk:req_node:otcc:4-1-1-4", "depth": 4, "ref_id": "4-1-1-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:4-1-1", "description": "Periodic cybersecurity assessment and audits of third-party providers must be conducted to ensure the mitigation of any identified cyber threats.", "implementation_groups": ["L1"]}, {"urn": "urn:intuitem:risk:req_node:otcc:4-1-2", "depth": 3, "ref_id": "4-1-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:otcc:4-1", "description": "With reference to the ECC control 4-1-4, the cybersecurity requirements for third-party cybersecurity in OT/ICS environment must be reviewed, and their implementation effectiveness is measured and evaluated periodically.", "implementation_groups": ["L1", "L2"]}], "implementation_groups_definition": [{"name": "Control Level 1", "ref_id": "L1", "description": "The criticality level of the facility is high and have severe adverse effects, consequences, and/or impacts to operations, catastrophic or assets, resources, or Health, Safety, and Environment (HSE) of the organization."}, {"name": "Control Level 2", "ref_id": "L2", "description": "The criticality level of the facility is moderate and have significant effects, consequences, and/or impacts to operations, assets, resources, or Health, Safety, and Environment (HSE) of the organization."}, {"name": "Control Level 3", "ref_id": "L3", "description": "The criticality level of the facility is low and have moderate adverse effects, consequences, and/or impacts to operations, assets, resources, or Health, Safety, and Environment (HSE) of the organization."}]}}	f
114ade23-5951-43c8-8441-933fb6a8bb88	2026-04-05 13:57:28.737539+00	2026-04-05 13:57:28.737539+00	f	urn:intuitem:risk:library:sama-csf	SAMA-CSF	SAMA	SAMA Cyber Security Framework	The Saudi Arabian Monetary Authority (SAMA) Cyber Security Framework provides a comprehensive set of cyber security principles and objectives to help member organizations develop their cyber security capabilities. The framework is mandatory for all financial institutions regulated by SAMA.\n\nhttps://www.sama.gov.sa/en-US/RulesInstructions/CyberSecurity/Pages/default.aspx	\N	\N	en	t	Saudi Arabian Monetary Authority (SAMA)	1	intuitem	2017-05-01	f	{}	\N	f	fa7e13ac05d3a759bfc749560a2460e22048be9474b4c6d35bf9a5e31e6abf59	{"framework": {"urn": "urn:intuitem:risk:framework:sama-csf", "name": "SAMA Cyber Security Framework", "ref_id": "SAMA-CSF", "description": "The Saudi Arabian Monetary Authority (SAMA) Cyber Security Framework provides cyber security principles and objectives for financial institutions.", "requirement_nodes": [{"urn": "urn:intuitem:risk:req_node:sama-csf:1", "name": "Cyber Security Leadership and Governance", "depth": 1, "ref_id": "1", "assessable": false}, {"urn": "urn:intuitem:risk:req_node:sama-csf:1.1", "name": "Cyber Security Strategy", "depth": 2, "ref_id": "1.1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:1"}, {"urn": "urn:intuitem:risk:req_node:sama-csf:1.1.1", "depth": 3, "ref_id": "1.1.1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:1.1", "description": "The Member Organization shall define and document a cyber security strategy that is aligned with the organization's business strategy and objectives."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:1.1.2", "depth": 3, "ref_id": "1.1.2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:1.1", "description": "The cyber security strategy shall be reviewed and updated at least annually or when there are significant changes to the business or threat environment."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:1.1.3", "depth": 3, "ref_id": "1.1.3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:1.1", "description": "The cyber security strategy shall be approved by the Board of Directors or equivalent governing body."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:1.2", "name": "Cyber Security Governance", "depth": 2, "ref_id": "1.2", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:1"}, {"urn": "urn:intuitem:risk:req_node:sama-csf:1.2.1", "depth": 3, "ref_id": "1.2.1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:1.2", "description": "The Member Organization shall establish a cyber security governance structure with clearly defined roles, responsibilities, and accountability."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:1.2.2", "depth": 3, "ref_id": "1.2.2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:1.2", "description": "A dedicated cyber security function shall be established, led by a Chief Information Security Officer (CISO) or equivalent role."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:1.2.3", "depth": 3, "ref_id": "1.2.3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:1.2", "description": "The CISO or equivalent shall report directly to senior management and have regular access to the Board or relevant committees."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:1.2.4", "depth": 3, "ref_id": "1.2.4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:1.2", "description": "Cyber security governance shall be integrated with the organization's overall corporate governance framework."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:1.3", "name": "Cyber Security Policies and Procedures", "depth": 2, "ref_id": "1.3", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:1"}, {"urn": "urn:intuitem:risk:req_node:sama-csf:1.3.1", "depth": 3, "ref_id": "1.3.1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:1.3", "description": "The Member Organization shall develop and maintain comprehensive cyber security policies covering all domains of the framework."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:1.3.2", "depth": 3, "ref_id": "1.3.2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:1.3", "description": "Cyber security policies shall be approved by senior management and communicated to all relevant stakeholders."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:1.3.3", "depth": 3, "ref_id": "1.3.3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:1.3", "description": "Detailed procedures shall be developed to support the implementation of cyber security policies."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:1.3.4", "depth": 3, "ref_id": "1.3.4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:1.3", "description": "Policies and procedures shall be reviewed and updated at least annually or when significant changes occur."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:1.4", "name": "Cyber Security Roles and Responsibilities", "depth": 2, "ref_id": "1.4", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:1"}, {"urn": "urn:intuitem:risk:req_node:sama-csf:1.4.1", "depth": 3, "ref_id": "1.4.1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:1.4", "description": "Cyber security roles and responsibilities shall be clearly defined for all employees, contractors, and third parties."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:1.4.2", "depth": 3, "ref_id": "1.4.2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:1.4", "description": "Segregation of duties shall be implemented to prevent conflicts of interest and reduce the risk of fraud."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:1.4.3", "depth": 3, "ref_id": "1.4.3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:1.4", "description": "Job descriptions shall include cyber security responsibilities appropriate to each role."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:2", "name": "Cyber Security Risk Management and Compliance", "depth": 1, "ref_id": "2", "assessable": false}, {"urn": "urn:intuitem:risk:req_node:sama-csf:2.1", "name": "Cyber Security Risk Management", "depth": 2, "ref_id": "2.1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:2"}, {"urn": "urn:intuitem:risk:req_node:sama-csf:2.1.1", "depth": 3, "ref_id": "2.1.1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:2.1", "description": "The Member Organization shall establish a cyber security risk management framework integrated with enterprise risk management."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:2.1.2", "depth": 3, "ref_id": "2.1.2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:2.1", "description": "Cyber security risk assessments shall be conducted at least annually and when significant changes occur."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:2.1.3", "depth": 3, "ref_id": "2.1.3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:2.1", "description": "A cyber security risk register shall be maintained and regularly updated."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:2.1.4", "depth": 3, "ref_id": "2.1.4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:2.1", "description": "Risk treatment plans shall be developed and implemented for identified cyber security risks."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:2.1.5", "depth": 3, "ref_id": "2.1.5", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:2.1", "description": "Risk acceptance decisions shall be documented and approved by appropriate management levels."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:2.2", "name": "Regulatory Compliance", "depth": 2, "ref_id": "2.2", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:2"}, {"urn": "urn:intuitem:risk:req_node:sama-csf:2.2.1", "depth": 3, "ref_id": "2.2.1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:2.2", "description": "The Member Organization shall identify and comply with all applicable cyber security laws, regulations, and contractual requirements."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:2.2.2", "depth": 3, "ref_id": "2.2.2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:2.2", "description": "A compliance monitoring program shall be established to ensure ongoing adherence to regulatory requirements."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:2.2.3", "depth": 3, "ref_id": "2.2.3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:2.2", "description": "Compliance gaps shall be identified, documented, and remediated in a timely manner."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:2.3", "name": "Cyber Security Audit", "depth": 2, "ref_id": "2.3", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:2"}, {"urn": "urn:intuitem:risk:req_node:sama-csf:2.3.1", "depth": 3, "ref_id": "2.3.1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:2.3", "description": "Internal cyber security audits shall be conducted at least annually by qualified personnel."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:2.3.2", "depth": 3, "ref_id": "2.3.2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:2.3", "description": "External cyber security audits shall be conducted by independent third parties at least every two years."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:2.3.3", "depth": 3, "ref_id": "2.3.3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:2.3", "description": "Audit findings shall be tracked and remediated according to their severity."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3", "name": "Cyber Security Operations and Technology", "depth": 1, "ref_id": "3", "assessable": false}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.1", "name": "Human Resources Security", "depth": 2, "ref_id": "3.1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3"}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.1.1", "depth": 3, "ref_id": "3.1.1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.1", "description": "Background verification checks shall be conducted for all employees with access to sensitive information or systems."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.1.2", "depth": 3, "ref_id": "3.1.2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.1", "description": "Employment contracts shall include cyber security responsibilities and confidentiality agreements."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.1.3", "depth": 3, "ref_id": "3.1.3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.1", "description": "Employee termination procedures shall include revocation of access rights and return of assets."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.2", "name": "Cyber Security Awareness and Training", "depth": 2, "ref_id": "3.2", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3"}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.2.1", "depth": 3, "ref_id": "3.2.1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.2", "description": "A cyber security awareness program shall be established for all employees and contractors."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.2.2", "depth": 3, "ref_id": "3.2.2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.2", "description": "Cyber security awareness training shall be provided upon hiring and refreshed at least annually."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.2.3", "depth": 3, "ref_id": "3.2.3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.2", "description": "Role-specific cyber security training shall be provided to employees with elevated privileges or access to sensitive systems."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.2.4", "depth": 3, "ref_id": "3.2.4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.2", "description": "The effectiveness of awareness and training programs shall be measured and improved continuously."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.3", "name": "Asset Management", "depth": 2, "ref_id": "3.3", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3"}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.3.1", "depth": 3, "ref_id": "3.3.1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.3", "description": "An inventory of all information assets shall be maintained and regularly updated."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.3.2", "depth": 3, "ref_id": "3.3.2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.3", "description": "Asset owners shall be assigned for all critical information assets."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.3.3", "depth": 3, "ref_id": "3.3.3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.3", "description": "Information assets shall be classified based on their criticality and sensitivity."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.3.4", "depth": 3, "ref_id": "3.3.4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.3", "description": "Acceptable use policies shall be defined for information assets."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.4", "name": "Identity and Access Management", "depth": 2, "ref_id": "3.4", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3"}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.4.1", "depth": 3, "ref_id": "3.4.1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.4", "description": "A formal access control policy shall be defined based on the principle of least privilege."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.4.2", "depth": 3, "ref_id": "3.4.2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.4", "description": "User access management processes shall cover the entire access lifecycle from provisioning to de-provisioning."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.4.3", "depth": 3, "ref_id": "3.4.3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.4", "description": "Privileged access shall be strictly controlled, monitored, and reviewed regularly."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.4.4", "depth": 3, "ref_id": "3.4.4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.4", "description": "Multi-factor authentication shall be implemented for remote access and access to critical systems."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.4.5", "depth": 3, "ref_id": "3.4.5", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.4", "description": "User access rights shall be reviewed at least quarterly for critical systems and semi-annually for other systems."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.4.6", "depth": 3, "ref_id": "3.4.6", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.4", "description": "Strong password policies shall be enforced across all systems."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.5", "name": "Network Security", "depth": 2, "ref_id": "3.5", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3"}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.5.1", "depth": 3, "ref_id": "3.5.1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.5", "description": "Network architecture shall be designed with security in mind, implementing defense in depth principles."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.5.2", "depth": 3, "ref_id": "3.5.2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.5", "description": "Network segmentation shall be implemented to separate critical systems and sensitive data."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.5.3", "depth": 3, "ref_id": "3.5.3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.5", "description": "Firewalls shall be deployed at network perimeters and between network segments."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.5.4", "depth": 3, "ref_id": "3.5.4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.5", "description": "Intrusion detection and prevention systems shall be deployed to monitor network traffic."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.5.5", "depth": 3, "ref_id": "3.5.5", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.5", "description": "Wireless networks shall be secured and segregated from the production network."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.5.6", "depth": 3, "ref_id": "3.5.6", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.5", "description": "Remote access shall be secured using encrypted connections and multi-factor authentication."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.6", "name": "System Security", "depth": 2, "ref_id": "3.6", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3"}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.6.1", "depth": 3, "ref_id": "3.6.1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.6", "description": "Security hardening standards shall be defined and applied to all systems."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.6.2", "depth": 3, "ref_id": "3.6.2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.6", "description": "Operating systems and applications shall be kept updated with security patches."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.6.3", "depth": 3, "ref_id": "3.6.3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.6", "description": "Anti-malware solutions shall be deployed on all endpoints and servers."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.6.4", "depth": 3, "ref_id": "3.6.4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.6", "description": "Change management procedures shall be followed for all system changes."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.6.5", "depth": 3, "ref_id": "3.6.5", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.6", "description": "System clocks shall be synchronized with trusted time sources."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.7", "name": "Application Security", "depth": 2, "ref_id": "3.7", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3"}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.7.1", "depth": 3, "ref_id": "3.7.1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.7", "description": "Secure software development lifecycle (SDLC) practices shall be implemented."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.7.2", "depth": 3, "ref_id": "3.7.2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.7", "description": "Security requirements shall be defined during the requirements phase of application development."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.7.3", "depth": 3, "ref_id": "3.7.3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.7", "description": "Code reviews and security testing shall be conducted before applications are deployed to production."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.7.4", "depth": 3, "ref_id": "3.7.4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.7", "description": "Web applications shall be protected against common vulnerabilities (OWASP Top 10)."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.7.5", "depth": 3, "ref_id": "3.7.5", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.7", "description": "Application security testing shall be conducted regularly, including penetration testing."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.8", "name": "Cryptography", "depth": 2, "ref_id": "3.8", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3"}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.8.1", "depth": 3, "ref_id": "3.8.1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.8", "description": "A cryptographic policy shall be defined specifying approved algorithms and key lengths."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.8.2", "depth": 3, "ref_id": "3.8.2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.8", "description": "Sensitive data shall be encrypted in transit and at rest using approved cryptographic methods."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.8.3", "depth": 3, "ref_id": "3.8.3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.8", "description": "Cryptographic keys shall be managed throughout their lifecycle, including generation, storage, distribution, and destruction."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.8.4", "depth": 3, "ref_id": "3.8.4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.8", "description": "Digital certificates shall be managed appropriately, including timely renewal and revocation."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.9", "name": "Data Protection", "depth": 2, "ref_id": "3.9", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3"}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.9.1", "depth": 3, "ref_id": "3.9.1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.9", "description": "Data classification scheme shall be defined and implemented across the organization."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.9.2", "depth": 3, "ref_id": "3.9.2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.9", "description": "Data handling procedures shall be defined based on data classification."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.9.3", "depth": 3, "ref_id": "3.9.3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.9", "description": "Data loss prevention (DLP) controls shall be implemented to prevent unauthorized data exfiltration."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.9.4", "depth": 3, "ref_id": "3.9.4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.9", "description": "Data retention and disposal policies shall be defined and implemented."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.9.5", "depth": 3, "ref_id": "3.9.5", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.9", "description": "Privacy requirements shall be addressed, including customer data protection."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.10", "name": "Physical and Environmental Security", "depth": 2, "ref_id": "3.10", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3"}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.10.1", "depth": 3, "ref_id": "3.10.1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.10", "description": "Physical security controls shall be implemented for facilities housing critical systems."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.10.2", "depth": 3, "ref_id": "3.10.2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.10", "description": "Access to secure areas shall be restricted and monitored."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.10.3", "depth": 3, "ref_id": "3.10.3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.10", "description": "Environmental controls shall be implemented to protect against natural and man-made disasters."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.10.4", "depth": 3, "ref_id": "3.10.4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.10", "description": "Equipment shall be protected against power failures and other utility disruptions."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.10.5", "depth": 3, "ref_id": "3.10.5", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.10", "description": "Secure disposal procedures shall be implemented for equipment and storage media."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.11", "name": "Security Monitoring", "depth": 2, "ref_id": "3.11", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3"}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.11.1", "depth": 3, "ref_id": "3.11.1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.11", "description": "Security event logging shall be enabled on all critical systems and applications."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.11.2", "depth": 3, "ref_id": "3.11.2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.11", "description": "Security logs shall be centralized and protected against tampering."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.11.3", "depth": 3, "ref_id": "3.11.3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.11", "description": "Security logs shall be retained according to regulatory and organizational requirements."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.11.4", "depth": 3, "ref_id": "3.11.4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.11", "description": "A Security Operations Center (SOC) or equivalent function shall be established for continuous monitoring."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.11.5", "depth": 3, "ref_id": "3.11.5", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.11", "description": "Security Information and Event Management (SIEM) solutions shall be deployed."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.12", "name": "Vulnerability Management", "depth": 2, "ref_id": "3.12", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3"}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.12.1", "depth": 3, "ref_id": "3.12.1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.12", "description": "A vulnerability management program shall be established covering all systems."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.12.2", "depth": 3, "ref_id": "3.12.2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.12", "description": "Vulnerability assessments shall be conducted at least quarterly for critical systems."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.12.3", "depth": 3, "ref_id": "3.12.3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.12", "description": "Penetration testing shall be conducted at least annually by qualified personnel."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.12.4", "depth": 3, "ref_id": "3.12.4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.12", "description": "Identified vulnerabilities shall be remediated based on their severity within defined timeframes."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:3.12.5", "depth": 3, "ref_id": "3.12.5", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:3.12", "description": "Threat intelligence shall be used to prioritize vulnerability remediation."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:4", "name": "Third Party Cyber Security", "depth": 1, "ref_id": "4", "assessable": false}, {"urn": "urn:intuitem:risk:req_node:sama-csf:4.1", "name": "Third Party Risk Management", "depth": 2, "ref_id": "4.1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:4"}, {"urn": "urn:intuitem:risk:req_node:sama-csf:4.1.1", "depth": 3, "ref_id": "4.1.1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:4.1", "description": "A third-party risk management framework shall be established covering the entire vendor lifecycle."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:4.1.2", "depth": 3, "ref_id": "4.1.2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:4.1", "description": "Due diligence assessments shall be conducted before engaging with third parties."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:4.1.3", "depth": 3, "ref_id": "4.1.3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:4.1", "description": "Third parties shall be classified based on the criticality of services provided and access to data."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:4.1.4", "depth": 3, "ref_id": "4.1.4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:4.1", "description": "Contracts with third parties shall include cyber security requirements and right to audit clauses."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:4.1.5", "depth": 3, "ref_id": "4.1.5", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:4.1", "description": "Third-party performance and compliance shall be monitored throughout the relationship."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:4.1.6", "depth": 3, "ref_id": "4.1.6", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:4.1", "description": "Exit strategies shall be defined for critical third-party relationships."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:4.2", "name": "Outsourcing Security", "depth": 2, "ref_id": "4.2", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:4"}, {"urn": "urn:intuitem:risk:req_node:sama-csf:4.2.1", "depth": 3, "ref_id": "4.2.1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:4.2", "description": "Outsourcing arrangements shall be governed by formal agreements including security requirements."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:4.2.2", "depth": 3, "ref_id": "4.2.2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:4.2", "description": "Service level agreements (SLAs) shall include security metrics and reporting requirements."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:4.2.3", "depth": 3, "ref_id": "4.2.3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:4.2", "description": "Access by outsourced service providers shall be monitored and controlled."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:4.3", "name": "Cloud Security", "depth": 2, "ref_id": "4.3", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:4"}, {"urn": "urn:intuitem:risk:req_node:sama-csf:4.3.1", "depth": 3, "ref_id": "4.3.1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:4.3", "description": "Cloud service usage shall be governed by a formal policy addressing security requirements."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:4.3.2", "depth": 3, "ref_id": "4.3.2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:4.3", "description": "Cloud service providers shall be assessed for security capabilities before engagement."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:4.3.3", "depth": 3, "ref_id": "4.3.3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:4.3", "description": "Data residency and sovereignty requirements shall be considered when using cloud services."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:4.3.4", "depth": 3, "ref_id": "4.3.4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:4.3", "description": "Shared responsibility models shall be understood and security controls implemented accordingly."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:5", "name": "Cyber Security Incident Management", "depth": 1, "ref_id": "5", "assessable": false}, {"urn": "urn:intuitem:risk:req_node:sama-csf:5.1", "name": "Incident Response", "depth": 2, "ref_id": "5.1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:5"}, {"urn": "urn:intuitem:risk:req_node:sama-csf:5.1.1", "depth": 3, "ref_id": "5.1.1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:5.1", "description": "An incident response plan shall be developed and maintained covering all types of cyber security incidents."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:5.1.2", "depth": 3, "ref_id": "5.1.2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:5.1", "description": "An incident response team shall be established with defined roles and responsibilities."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:5.1.3", "depth": 3, "ref_id": "5.1.3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:5.1", "description": "Incident classification and prioritization procedures shall be defined."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:5.1.4", "depth": 3, "ref_id": "5.1.4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:5.1", "description": "Communication procedures shall be defined for internal and external stakeholders during incidents."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:5.1.5", "depth": 3, "ref_id": "5.1.5", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:5.1", "description": "SAMA shall be notified of significant cyber security incidents within the required timeframe."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:5.1.6", "depth": 3, "ref_id": "5.1.6", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:5.1", "description": "Post-incident reviews shall be conducted and lessons learned documented."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:5.1.7", "depth": 3, "ref_id": "5.1.7", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:5.1", "description": "Incident response capabilities shall be tested at least annually through exercises."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:5.2", "name": "Digital Forensics", "depth": 2, "ref_id": "5.2", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:5"}, {"urn": "urn:intuitem:risk:req_node:sama-csf:5.2.1", "depth": 3, "ref_id": "5.2.1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:5.2", "description": "Digital forensics capabilities shall be established either internally or through third parties."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:5.2.2", "depth": 3, "ref_id": "5.2.2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:5.2", "description": "Evidence handling procedures shall be defined to maintain chain of custody."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:5.2.3", "depth": 3, "ref_id": "5.2.3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:5.2", "description": "Forensic investigation results shall be documented and preserved for potential legal proceedings."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:6", "name": "Cyber Security Business Continuity", "depth": 1, "ref_id": "6", "assessable": false}, {"urn": "urn:intuitem:risk:req_node:sama-csf:6.1", "name": "Business Continuity Planning", "depth": 2, "ref_id": "6.1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:6"}, {"urn": "urn:intuitem:risk:req_node:sama-csf:6.1.1", "depth": 3, "ref_id": "6.1.1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:6.1", "description": "Business Impact Analysis (BIA) shall be conducted to identify critical business functions and dependencies."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:6.1.2", "depth": 3, "ref_id": "6.1.2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:6.1", "description": "Business continuity plans shall be developed addressing cyber security incident scenarios."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:6.1.3", "depth": 3, "ref_id": "6.1.3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:6.1", "description": "Recovery Time Objectives (RTO) and Recovery Point Objectives (RPO) shall be defined for critical systems."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:6.1.4", "depth": 3, "ref_id": "6.1.4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:6.1", "description": "Business continuity plans shall be tested at least annually."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:6.2", "name": "Disaster Recovery", "depth": 2, "ref_id": "6.2", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:6"}, {"urn": "urn:intuitem:risk:req_node:sama-csf:6.2.1", "depth": 3, "ref_id": "6.2.1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:6.2", "description": "Disaster recovery plans shall be developed for critical systems and data."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:6.2.2", "depth": 3, "ref_id": "6.2.2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:6.2", "description": "Backup and recovery procedures shall be implemented for critical systems and data."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:6.2.3", "depth": 3, "ref_id": "6.2.3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:6.2", "description": "Backup data shall be stored securely at offsite locations."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:6.2.4", "depth": 3, "ref_id": "6.2.4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:6.2", "description": "Disaster recovery capabilities shall be tested at least annually."}, {"urn": "urn:intuitem:risk:req_node:sama-csf:6.2.5", "depth": 3, "ref_id": "6.2.5", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:sama-csf:6.2", "description": "Alternate processing sites shall be available for critical systems if required."}]}}	f
825290eb-2275-4a2a-91de-0fb6efddb750	2026-04-05 13:57:29.129924+00	2026-04-05 13:57:29.129924+00	f	urn:intuitem:risk:library:saudi-pdpl-1.0	SAUDI-PDPL-1.0	SDAIA	Saudi Arabia Personal Data Protection Law (PDPL)	Saudi Arabia Personal Data Protection Law (Royal Decree M/19), its Implementing Regulation, and the Regulation on Personal Data Transfer Outside the Kingdom.	\N	\N	en	t	Saudi Data and Artificial Intelligence Authority (SDAIA). All texts, layouts, designs and other elements of any nature in this document are subject to copyright law.	1	intuitem	2021-09-24	f	{}	\N	f	3d700969cf13bbcf5dd6f331364bec9ba6e3e8f009784c887833aa8267568cdf	{"framework": {"urn": "urn:intuitem:risk:framework:saudi-pdpl-1.0", "name": "Saudi Arabia Personal Data Protection Law (PDPL)", "ref_id": "SAUDI-PDPL-1.0", "scores": [{"name": "Non-compliant", "score": 0, "description": "No measures or controls have been implemented to address the requirement. There is no awareness of the obligation or it has been entirely disregarded."}, {"name": "Initial / Ad-hoc", "score": 1, "description": "Some measures exist but are ad-hoc, informal and inconsistent. Compliance depends on individual effort rather than systematic processes."}, {"name": "Developing", "score": 2, "description": "Policies or procedures are being developed or partially implemented. Compliance measures exist but are not yet fully documented or consistently applied."}, {"name": "Defined & Implemented", "score": 3, "description": "Policies and procedures are formally defined, approved and implemented in a structured manner. Compliance can be demonstrated through documentation and evidence."}, {"name": "Managed & Measured", "score": 4, "description": "Compliance controls are monitored, measured and periodically reviewed for effectiveness. Improvements are documented and applied based on assessment findings."}, {"name": "Optimized & Continuous Improvement", "score": 5, "description": "Compliance controls are subject to continuous improvement. Best practices are followed, controls are proactively adapted to regulatory changes, and the organization demonstrates leadership in data protection."}], "description": "Saudi Arabia Personal Data Protection Law (Royal Decree M/19), its Implementing Regulation, and the Regulation on Personal Data Transfer Outside the Kingdom.", "requirement_nodes": [{"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:personal-data-protection-law-royal-decree-m19", "name": "Personal Data Protection Law (Royal Decree M/19)", "depth": 1, "assessable": false}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:general-provisions", "name": "General Provisions", "depth": 2, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:personal-data-protection-law-royal-decree-m19"}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-1", "depth": 3, "ref_id": "PDPL-Art-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:general-provisions", "description": "This Law aims to protect the right of individuals to privacy by ensuring the confidentiality, integrity and availability of personal data. It regulates the collection, processing, disclosure and retention of personal data and establishes the rights and obligations of all relevant parties."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-2", "depth": 3, "ref_id": "PDPL-Art-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:general-provisions", "description": "The provisions of this Law shall apply to any processing of personal data relating to individuals that takes place in the Kingdom by any means, including the processing of personal data relating to residents of the Kingdom by any means by any entity outside the Kingdom. Processing of personal data for purely personal or family purposes shall be excluded."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-3", "depth": 3, "ref_id": "PDPL-Art-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:general-provisions", "description": "Words and expressions used in this Law shall have the meanings assigned to them in the Implementing Regulation, unless the context otherwise requires. Key terms include: personal data, sensitive data, processing, controller, data subject, consent, disclosure, and destruction of personal data."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:collection-and-processing-of-personal-data", "name": "Collection and Processing of Personal Data", "depth": 2, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:personal-data-protection-law-royal-decree-m19"}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-4", "depth": 3, "ref_id": "PDPL-Art-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:collection-and-processing-of-personal-data", "description": "Personal data shall not be collected except for a lawful, specific, clear and concrete purpose directly relating to the activity of the controller. The controller shall take the necessary measures to verify the accuracy and completeness of personal data and keep it updated where necessary to achieve the purpose of its collection."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-5", "depth": 3, "ref_id": "PDPL-Art-5", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:collection-and-processing-of-personal-data", "description": "The processing of personal data shall not take place without the consent of the data subject, except in specific cases prescribed by law, including: performance of a legal obligation, protection of a vital interest of the data subject, if the data subject has made the data manifestly public, or if processing is necessary for legitimate interests pursued by the controller."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-6", "depth": 3, "ref_id": "PDPL-Art-6", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:collection-and-processing-of-personal-data", "description": "Consent for the processing of personal data shall be given freely, explicitly, unambiguously and in a clear form. The data subject may withdraw consent at any time and, in such case, the withdrawal shall not affect the lawfulness of the processing based on consent given prior to its withdrawal. The controller shall provide an easy mechanism for withdrawing consent."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-7", "depth": 3, "ref_id": "PDPL-Art-7", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:collection-and-processing-of-personal-data", "description": "Personal data may be processed without the consent of the data subject in the following cases: (a) if the processing achieves a clear benefit for the data subject and it is impossible or difficult to contact them; (b) in accordance with another law or in implementation of a previous agreement to which the data subject is party; (c) if the controller is a public entity and the processing is required for security purposes or to fulfil a judicial requirement."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-8", "depth": 3, "ref_id": "PDPL-Art-8", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:collection-and-processing-of-personal-data", "description": "The controller shall, before collecting personal data, inform the data subject of the following: the legal basis and purpose for the collection, whether the provision of data is mandatory or optional and its consequences, the identity of any entity to which data will be disclosed, and the consequences of not providing consent where applicable."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-9", "depth": 3, "ref_id": "PDPL-Art-9", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:collection-and-processing-of-personal-data", "description": "Personal data shall not be retained after the purpose of its collection has been achieved or the specified period for retention has expired. The controller shall take the necessary procedures to destroy or anonymize personal data at the expiry of the retention period, except where another law requires its retention for a longer period."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-10", "depth": 3, "ref_id": "PDPL-Art-10", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:collection-and-processing-of-personal-data", "description": "Where a controller has collected personal data and wishes to process it for a purpose other than that for which it was collected, the controller shall obtain the consent of the data subject for the new purpose, unless the processing is for scientific, research or statistical purposes in accordance with the relevant regulations."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:rights-of-the-data-subject", "name": "Rights of the Data Subject", "depth": 2, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:personal-data-protection-law-royal-decree-m19"}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-11", "depth": 3, "ref_id": "PDPL-Art-11", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:rights-of-the-data-subject", "description": "The data subject shall have the right to be informed of the legal basis and purpose of the collection and processing of their personal data, and to know the mandatory or optional nature of its provision and the consequences of not providing or withdrawing consent."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-12", "depth": 3, "ref_id": "PDPL-Art-12", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:rights-of-the-data-subject", "description": "The data subject shall have the right to access their personal data held by the controller and to obtain a copy thereof, in accordance with the conditions and procedures set out in the Implementing Regulation."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-13", "depth": 3, "ref_id": "PDPL-Art-13", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:rights-of-the-data-subject", "description": "The data subject shall have the right to request the correction, completion or updating of their personal data where it is inaccurate, incomplete or out of date, in accordance with the conditions and procedures set out in the Implementing Regulation."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-14", "depth": 3, "ref_id": "PDPL-Art-14", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:rights-of-the-data-subject", "description": "The data subject shall have the right to request the destruction of their personal data when it is no longer necessary to retain it, in accordance with the conditions and procedures set out in the Implementing Regulation. The controller shall destroy the data within the period specified in the Implementing Regulation and notify all third parties to whom the data was disclosed."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-15", "depth": 3, "ref_id": "PDPL-Art-15", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:rights-of-the-data-subject", "description": "The data subject shall have the right to object to the processing of their personal data in certain cases specified in this Law and the Implementing Regulation, including where the processing is for direct marketing purposes."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:processing-of-sensitive-data", "name": "Processing of Sensitive Data", "depth": 2, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:personal-data-protection-law-royal-decree-m19"}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-16", "depth": 3, "ref_id": "PDPL-Art-16", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:processing-of-sensitive-data", "description": "Sensitive data includes data that reveals the racial or ethnic origin, religious, intellectual or political beliefs of a data subject, data relating to criminal records, biometric or genetic data for the purposes of identifying a natural person, health data and data indicating that the data subject is a child."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-17", "depth": 3, "ref_id": "PDPL-Art-17", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:processing-of-sensitive-data", "description": "The processing of sensitive data shall be prohibited unless it is necessary for the protection of the vital interests of the data subject, or the processing is carried out in accordance with a law, or the data subject has given explicit consent. The Implementing Regulation specifies additional cases in which sensitive data may be processed."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:personal-data-related-to-health", "name": "Personal Data Related to Health", "depth": 2, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:personal-data-protection-law-royal-decree-m19"}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-18", "depth": 3, "ref_id": "PDPL-Art-18", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:personal-data-related-to-health", "description": "The processing of health data shall comply with the provisions of this Law and any other applicable regulations. Health data may be processed without consent where necessary for public health purposes, medical diagnosis, provision of healthcare or treatment, or management of health systems and services."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:data-processing-for-minors", "name": "Data Processing for Minors", "depth": 2, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:personal-data-protection-law-royal-decree-m19"}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-19", "depth": 3, "ref_id": "PDPL-Art-19", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:data-processing-for-minors", "description": "The processing of personal data belonging to minors (persons under the age of eighteen) shall be governed by the conditions set by the Implementing Regulation. Consent for data processing of a minor shall be obtained from the parent or legal guardian."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:obligations-of-the-controller", "name": "Obligations of the Controller", "depth": 2, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:personal-data-protection-law-royal-decree-m19"}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-20", "depth": 3, "ref_id": "PDPL-Art-20", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:obligations-of-the-controller", "description": "The controller shall implement appropriate technical and organizational measures to ensure that the processing of personal data is carried out in accordance with this Law and the Implementing Regulation. These measures shall be reviewed and updated periodically."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-21", "depth": 3, "ref_id": "PDPL-Art-21", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:obligations-of-the-controller", "description": "The controller shall maintain records of the personal data processing operations it carries out, including: the purpose of processing, the categories of data subjects and personal data, the period of retention, a description of the technical and organizational security measures, and any cross-border transfers of personal data."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-22", "depth": 3, "ref_id": "PDPL-Art-22", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:obligations-of-the-controller", "description": "The controller shall conduct a personal data impact assessment prior to carrying out any processing that is likely to result in a high risk to the privacy of data subjects. The assessment shall include: the nature and scope of the processing, the risks to the data subject, and the measures to mitigate those risks."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-23", "depth": 3, "ref_id": "PDPL-Art-23", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:obligations-of-the-controller", "description": "The controller shall appoint a data protection officer when required by the Implementing Regulation. The data protection officer shall be responsible for monitoring compliance with this Law and the Implementing Regulation and shall report directly to the highest level of management of the controller."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-24", "depth": 3, "ref_id": "PDPL-Art-24", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:obligations-of-the-controller", "description": "In the event of a personal data breach, the controller shall notify the competent authority within the period specified in the Implementing Regulation. Where the breach is likely to cause serious harm to the data subject, the controller shall also notify the data subject without undue delay."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-25", "depth": 3, "ref_id": "PDPL-Art-25", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:obligations-of-the-controller", "description": "The controller that engages a processor to process personal data on its behalf shall enter into a written agreement with the processor specifying: the nature and purpose of the processing, the type of personal data, the duration of processing, the obligations and rights of the controller, and the obligation of the processor to comply with this Law."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:processing-for-marketing-purposes", "name": "Processing for Marketing Purposes", "depth": 2, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:personal-data-protection-law-royal-decree-m19"}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-26", "depth": 3, "ref_id": "PDPL-Art-26", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:processing-for-marketing-purposes", "description": "The processing of personal data for direct marketing purposes requires the consent of the data subject. The data subject shall have the right to object at any time to the processing of their data for direct marketing purposes. Where the data subject objects, the controller shall cease processing for such purposes."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:disclosure-and-transfer-of-personal-data", "name": "Disclosure and Transfer of Personal Data", "depth": 2, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:personal-data-protection-law-royal-decree-m19"}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-27", "depth": 3, "ref_id": "PDPL-Art-27", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:disclosure-and-transfer-of-personal-data", "description": "Personal data shall not be disclosed to any entity except with the consent of the data subject or in the cases specified in this Law. Disclosure may be made without consent to competent public authorities for security purposes, to fulfil legal obligations, or to protect the vital interests of the data subject."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-28", "depth": 3, "ref_id": "PDPL-Art-28", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:disclosure-and-transfer-of-personal-data", "description": "Personal data shall not be transferred outside the Kingdom except in accordance with the conditions set out in this Law, the Implementing Regulation, and the Regulation on Personal Data Transfer Outside the Kingdom. Transfer may be permitted where: the receiving country provides an adequate level of protection, or appropriate safeguards are in place."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-29", "depth": 3, "ref_id": "PDPL-Art-29", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:disclosure-and-transfer-of-personal-data", "description": "The controller shall ensure that any cross-border transfer of personal data does not jeopardize national security or vital interests of the Kingdom. The competent authority may restrict or prohibit the transfer of certain categories of personal data outside the Kingdom."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:penalties-and-enforcement", "name": "Penalties and Enforcement", "depth": 2, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:personal-data-protection-law-royal-decree-m19"}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-30", "depth": 3, "ref_id": "PDPL-Art-30", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:penalties-and-enforcement", "description": "Without prejudice to any more severe penalty prescribed in another law, any person who violates the provisions relating to the transfer of personal data outside the Kingdom in violation of this Law shall be punished by imprisonment for a period not exceeding two years and a fine not exceeding three million riyals, or either of these penalties."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-31", "depth": 3, "ref_id": "PDPL-Art-31", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:penalties-and-enforcement", "description": "Without prejudice to any more severe penalty prescribed in another law, any person who discloses sensitive data in violation of this Law with the intention of causing harm to the data subject or achieving a personal benefit shall be punished by imprisonment for a period not exceeding two years and a fine not exceeding three million riyals, or either of these penalties."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-32", "depth": 3, "ref_id": "PDPL-Art-32", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:penalties-and-enforcement", "description": "The competent authority may impose a warning, or a fine not exceeding five million riyals, against any person who violates any of the provisions of this Law or the Implementing Regulation. In the event of a repeated violation, the fine may be doubled. The competent court may order the publication of the judgment at the expense of the violator."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-33", "depth": 3, "ref_id": "PDPL-Art-33", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:penalties-and-enforcement", "description": "Criminal cases and penalties relating to violations of this Law shall be considered by the competent court. The competent authority shall have the right to investigate violations and refer them to the Public Prosecution."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:final-provisions", "name": "Final Provisions", "depth": 2, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:personal-data-protection-law-royal-decree-m19"}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-34", "depth": 3, "ref_id": "PDPL-Art-34", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:final-provisions", "description": "The competent authority shall be responsible for the supervision, monitoring and enforcement of the provisions of this Law and the Implementing Regulation. It shall have the power to issue decisions, regulations and procedures necessary for implementation."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-35", "depth": 3, "ref_id": "PDPL-Art-35", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:final-provisions", "description": "Public and private entities processing personal data shall adjust their status in accordance with the provisions of this Law within a period not exceeding one year from the date of its entry into force, unless otherwise specified by the competent authority."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-36", "depth": 3, "ref_id": "PDPL-Art-36", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:final-provisions", "description": "The Implementing Regulation shall be issued by resolution of the competent authority within one hundred and eighty days from the date of publication of this Law. The provisions of this Law shall come into force upon the expiry of the period for adjusting status."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-37", "depth": 3, "ref_id": "PDPL-Art-37", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:final-provisions", "description": "The competent authority may grant additional extensions to the adjustment period for entities that demonstrate a legitimate need for additional time to achieve compliance, subject to conditions determined by the competent authority."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-38", "depth": 3, "ref_id": "PDPL-Art-38", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:final-provisions", "description": "The provisions of this Law shall apply to the processing of personal data that takes place after its entry into force. Processing that was initiated before its entry into force shall be adjusted in accordance with the provisions of this Law within the adjustment period."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-39", "depth": 3, "ref_id": "PDPL-Art-39", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:final-provisions", "description": "Without prejudice to the provisions of this Law, national data relating to security and vital national interests shall be subject to such special rules as may be issued by the Council of Ministers."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-40", "depth": 3, "ref_id": "PDPL-Art-40", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:final-provisions", "description": "The competent authority shall establish and maintain a national register of controllers and processors. All entities processing personal data shall register with the competent authority in accordance with the conditions and procedures set out in the Implementing Regulation."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-41", "depth": 3, "ref_id": "PDPL-Art-41", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:final-provisions", "description": "The competent authority may cooperate and exchange information with foreign data protection authorities for the purpose of enforcing this Law and ensuring the protection of personal data, subject to the applicable regulations and the requirement of reciprocity."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-42", "depth": 3, "ref_id": "PDPL-Art-42", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:final-provisions", "description": "The provisions of this Law shall be without prejudice to the obligations arising from international agreements to which the Kingdom is party."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:pdpl-art-43", "depth": 3, "ref_id": "PDPL-Art-43", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:final-provisions", "description": "This Law shall be published in the Official Gazette and shall come into force in accordance with the provisions of Article 36."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:implementing-regulation-of-the-personal-data-protection-law", "name": "Implementing Regulation of the Personal Data Protection Law", "depth": 1, "assessable": false}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:general-provisions-and-definitions", "name": "General Provisions and Definitions", "depth": 2, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:implementing-regulation-of-the-personal-data-protection-law"}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-1", "depth": 3, "ref_id": "IR-Art-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:general-provisions-and-definitions", "description": "This regulation defines the terms and expressions used in the Personal Data Protection Law, including but not limited to: personal data, sensitive data, processing, controller, processor, data subject, consent, disclosure, destruction, anonymization, pseudonymization, cross-border transfer, personal data breach, and competent authority (SDAIA)."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-2", "depth": 3, "ref_id": "IR-Art-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:general-provisions-and-definitions", "description": "The Implementing Regulation governs the procedures and conditions for the application of the Personal Data Protection Law. It establishes detailed requirements for controllers, processors, and other entities involved in the processing of personal data within and outside the Kingdom."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:legal-basis-and-conditions-for-personal-data-processing", "name": "Legal Basis and Conditions for Personal Data Processing", "depth": 2, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:implementing-regulation-of-the-personal-data-protection-law"}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-3", "depth": 3, "ref_id": "IR-Art-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:legal-basis-and-conditions-for-personal-data-processing", "description": "The controller shall determine the legal basis for processing personal data prior to the commencement of processing. The legal basis shall be one of the following: consent of the data subject, performance of a contract, compliance with a legal obligation, protection of vital interests, performance of a task in the public interest, or legitimate interests of the controller."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-4", "depth": 3, "ref_id": "IR-Art-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:legal-basis-and-conditions-for-personal-data-processing", "description": "Consent of the data subject shall meet the following conditions: (a) freely given without coercion or deception; (b) specific to a particular purpose; (c) informed, meaning the data subject understands what they are consenting to; (d) unambiguous indication by clear affirmative action. Silence, pre-ticked boxes, or inactivity shall not constitute consent."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-5", "depth": 3, "ref_id": "IR-Art-5", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:legal-basis-and-conditions-for-personal-data-processing", "description": "The controller shall implement mechanisms to obtain, record and manage consent, including: maintaining a record of consent; providing clear information at the time of obtaining consent; enabling withdrawal of consent through an easy mechanism; and ceasing processing upon withdrawal."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-6", "depth": 3, "ref_id": "IR-Art-6", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:legal-basis-and-conditions-for-personal-data-processing", "description": "The controller shall ensure that personal data is processed lawfully, fairly and in a transparent manner. Processing shall be limited to what is necessary in relation to the purposes for which it is processed (data minimization). Personal data shall be accurate and, where necessary, kept up to date."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:rights-of-the-data-subject---implementing-procedures", "name": "Rights of the Data Subject - Implementing Procedures", "depth": 2, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:implementing-regulation-of-the-personal-data-protection-law"}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-7", "depth": 3, "ref_id": "IR-Art-7", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:rights-of-the-data-subject---implementing-procedures", "description": "The controller shall establish clear and accessible procedures for data subjects to exercise their rights under the Law. Requests from data subjects shall be responded to without undue delay and in any event within thirty (30) days of receipt of the request. The response period may be extended by an additional thirty (30) days where justified by the complexity of the request."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-8", "depth": 3, "ref_id": "IR-Art-8", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:rights-of-the-data-subject---implementing-procedures", "description": "The right of access shall include providing the data subject with the following information: (a) confirmation of whether personal data is being processed; (b) a copy of the personal data in an intelligible form; (c) the purpose of processing; (d) the categories of personal data; (e) the recipients or categories of recipients; (f) the retention period; (g) the existence of automated decision-making."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-9", "depth": 3, "ref_id": "IR-Art-9", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:rights-of-the-data-subject---implementing-procedures", "description": "The controller shall respond to correction requests by verifying the accuracy of existing data and implementing corrections within the specified period. The controller shall notify all recipients to whom the data has been disclosed of any corrections."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-10", "depth": 3, "ref_id": "IR-Art-10", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:rights-of-the-data-subject---implementing-procedures", "description": "The controller shall implement procedures for the destruction of personal data upon request by the data subject or upon expiry of the retention period. Destruction shall render the data irrecoverable. The controller shall certify the destruction and maintain records thereof."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-11", "depth": 3, "ref_id": "IR-Art-11", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:rights-of-the-data-subject---implementing-procedures", "description": "The controller shall provide the data subject with a mechanism to object to the processing of their personal data. Where the data subject objects, the controller shall cease processing unless the controller demonstrates compelling legitimate grounds that override the interests of the data subject."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:sensitive-data-processing-requirements", "name": "Sensitive Data Processing Requirements", "depth": 2, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:implementing-regulation-of-the-personal-data-protection-law"}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-12", "depth": 3, "ref_id": "IR-Art-12", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:sensitive-data-processing-requirements", "description": "The processing of sensitive data shall require explicit consent from the data subject, which must be separate from any other consent. The controller shall implement enhanced security measures for the protection of sensitive data. A Data Protection Impact Assessment shall be conducted before processing sensitive data."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-13", "depth": 3, "ref_id": "IR-Art-13", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:sensitive-data-processing-requirements", "description": "Health data may be processed without consent where necessary for: (a) public health monitoring and protection against serious cross-border health threats; (b) medical diagnosis and provision of health or social care; (c) management of health systems and services; (d) scientific or historical research or statistical purposes in the health field."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-14", "depth": 3, "ref_id": "IR-Art-14", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:sensitive-data-processing-requirements", "description": "Biometric data and genetic data shall be subject to additional safeguards, including: restriction of access to authorized personnel only; encryption during storage and transmission; regular auditing of access; and prohibition of processing for purposes incompatible with the original purpose of collection."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:data-processing-for-minors---implementing-procedures", "name": "Data Processing for Minors - Implementing Procedures", "depth": 2, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:implementing-regulation-of-the-personal-data-protection-law"}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-15", "depth": 3, "ref_id": "IR-Art-15", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:data-processing-for-minors---implementing-procedures", "description": "The processing of personal data of minors shall require the consent of the parent or legal guardian. The controller shall make reasonable efforts to verify that consent is provided by the parent or guardian. The controller shall provide privacy information in a manner that is understandable by the minor."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:controller-and-processor-obligations", "name": "Controller and Processor Obligations", "depth": 2, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:implementing-regulation-of-the-personal-data-protection-law"}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-16", "depth": 3, "ref_id": "IR-Art-16", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:controller-and-processor-obligations", "description": "The controller shall implement appropriate technical and organizational measures to ensure and demonstrate that processing is performed in accordance with this Law. These measures shall include, as appropriate: (a) pseudonymization and encryption; (b) ongoing confidentiality, integrity, availability and resilience of processing systems; (c) the ability to restore availability and access in a timely manner; (d) a process for regularly testing and evaluating measures."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-17", "depth": 3, "ref_id": "IR-Art-17", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:controller-and-processor-obligations", "description": "The controller shall maintain a comprehensive record of processing activities (ROPA) containing at minimum: (a) name and contact details of the controller; (b) purposes of processing; (c) categories of data subjects and personal data; (d) categories of recipients; (e) cross-border transfers; (f) retention periods; (g) description of security measures."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-18", "depth": 3, "ref_id": "IR-Art-18", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:controller-and-processor-obligations", "description": "The controller shall conduct a Data Protection Impact Assessment (DPIA) prior to processing that is likely to result in high risk to the rights of data subjects. High risk processing includes: (a) systematic and extensive profiling; (b) large-scale processing of sensitive data; (c) systematic monitoring of publicly accessible areas; (d) use of new technologies."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-19", "depth": 3, "ref_id": "IR-Art-19", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:controller-and-processor-obligations", "description": "The controller shall appoint a Data Protection Officer (DPO) where: (a) the controller is a public entity; (b) the core activities of the controller require large-scale, regular and systematic monitoring; (c) the core activities consist of large-scale processing of sensitive data. The DPO shall be provided with adequate resources and shall not be penalized for performing their duties."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:personal-data-breach-notification", "name": "Personal Data Breach Notification", "depth": 2, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:implementing-regulation-of-the-personal-data-protection-law"}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-20", "depth": 3, "ref_id": "IR-Art-20", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:personal-data-breach-notification", "description": "The controller shall notify the competent authority of any personal data breach without undue delay and no later than seventy-two (72) hours after becoming aware of the breach. The notification shall include: (a) the nature of the breach; (b) the categories and approximate number of data subjects affected; (c) the likely consequences; (d) the measures taken or proposed to address the breach."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-21", "depth": 3, "ref_id": "IR-Art-21", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:personal-data-breach-notification", "description": "Where the personal data breach is likely to result in a high risk to the rights of data subjects, the controller shall notify the affected data subjects without undue delay. The notification shall include: (a) the nature of the breach in clear and plain language; (b) the name and contact details of the DPO; (c) the likely consequences; (d) the measures taken to address the breach and mitigate its effects."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-22", "depth": 3, "ref_id": "IR-Art-22", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:personal-data-breach-notification", "description": "The controller shall maintain a register of all personal data breaches, including the facts, effects and remedial actions taken. The register shall be available for inspection by the competent authority."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:processor-requirements", "name": "Processor Requirements", "depth": 2, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:implementing-regulation-of-the-personal-data-protection-law"}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-23", "depth": 3, "ref_id": "IR-Art-23", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:processor-requirements", "description": "The processor shall process personal data only on documented instructions from the controller. The processor shall ensure that persons authorized to process personal data have committed themselves to confidentiality. The processor shall implement appropriate technical and organizational security measures."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-24", "depth": 3, "ref_id": "IR-Art-24", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:processor-requirements", "description": "The processor shall not engage another processor without prior written authorization of the controller. Where a processor engages a sub-processor, the same data protection obligations shall be imposed through a contract. The processor shall remain fully liable for the performance of the sub-processor."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:data-protection-by-design-and-default", "name": "Data Protection by Design and Default", "depth": 2, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:implementing-regulation-of-the-personal-data-protection-law"}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-25", "depth": 3, "ref_id": "IR-Art-25", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:data-protection-by-design-and-default", "description": "The controller shall implement appropriate technical and organizational measures designed to implement data protection principles in an effective manner and to integrate the necessary safeguards into the processing. At the time of determining the means for processing and at the time of the processing itself, the controller shall implement measures such as pseudonymization."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-26", "depth": 3, "ref_id": "IR-Art-26", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:data-protection-by-design-and-default", "description": "The controller shall implement appropriate measures for ensuring that, by default, only personal data which is necessary for each specific purpose is processed. This applies to the amount of data collected, the extent of processing, the period of storage, and accessibility."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:anonymization-and-pseudonymization", "name": "Anonymization and Pseudonymization", "depth": 2, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:implementing-regulation-of-the-personal-data-protection-law"}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-27", "depth": 3, "ref_id": "IR-Art-27", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:anonymization-and-pseudonymization", "description": "Where the purposes of processing can be achieved through anonymized data, the controller shall anonymize the data. Anonymized data is data that cannot, by any reasonable means, be linked to a specific or identifiable individual. The provisions of this Law shall not apply to anonymized data."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-28", "depth": 3, "ref_id": "IR-Art-28", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:anonymization-and-pseudonymization", "description": "Where pseudonymization is used, the additional information required for attribution to a specific data subject shall be kept separately and subject to technical and organizational measures to ensure non-attribution. Pseudonymized data shall remain subject to the provisions of this Law."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:privacy-notices-and-transparency", "name": "Privacy Notices and Transparency", "depth": 2, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:implementing-regulation-of-the-personal-data-protection-law"}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-29", "depth": 3, "ref_id": "IR-Art-29", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:privacy-notices-and-transparency", "description": "The controller shall provide privacy notices to data subjects at the time of collection. The privacy notice shall include: (a) the identity and contact details of the controller and DPO; (b) the purposes and legal basis of processing; (c) the categories of personal data; (d) the recipients; (e) cross-border transfers; (f) the retention period; (g) the rights of the data subject; (h) the right to lodge a complaint."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-30", "depth": 3, "ref_id": "IR-Art-30", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:privacy-notices-and-transparency", "description": "Privacy notices shall be provided in a concise, transparent, intelligible and easily accessible form, using clear and plain language. Where personal data is not collected directly from the data subject, the controller shall provide the privacy notice within a reasonable period after obtaining the data."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:direct-marketing-requirements", "name": "Direct Marketing Requirements", "depth": 2, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:implementing-regulation-of-the-personal-data-protection-law"}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-31", "depth": 3, "ref_id": "IR-Art-31", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:direct-marketing-requirements", "description": "The controller shall obtain explicit, prior consent from the data subject before processing personal data for direct marketing purposes. The consent request shall be clearly distinguishable from any other request for consent. The data subject shall be informed of the right to object to direct marketing at any time."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-32", "depth": 3, "ref_id": "IR-Art-32", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:direct-marketing-requirements", "description": "Where the data subject objects to processing for direct marketing, the controller shall cease processing without undue delay and no later than the period specified in this Regulation. The controller shall maintain a suppression list to ensure data subjects who have objected are not contacted."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:automated-decision-making-and-profiling", "name": "Automated Decision-Making and Profiling", "depth": 2, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:implementing-regulation-of-the-personal-data-protection-law"}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-33", "depth": 3, "ref_id": "IR-Art-33", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:automated-decision-making-and-profiling", "description": "The data subject shall have the right not to be subject to a decision based solely on automated processing, including profiling, which produces legal effects or similarly significantly affects the data subject. This right shall not apply where the decision is necessary for the performance of a contract, authorized by law, or based on explicit consent."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-34", "depth": 3, "ref_id": "IR-Art-34", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:automated-decision-making-and-profiling", "description": "Where automated decision-making is permitted, the controller shall implement suitable measures to safeguard the rights of the data subject, including the right to obtain human intervention, to express their point of view, and to contest the decision."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:supervisory-authority-and-enforcement", "name": "Supervisory Authority and Enforcement", "depth": 2, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:implementing-regulation-of-the-personal-data-protection-law"}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-35", "depth": 3, "ref_id": "IR-Art-35", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:supervisory-authority-and-enforcement", "description": "The competent authority (SDAIA) shall supervise compliance with the provisions of the Law and this Regulation. It shall have the power to: (a) conduct investigations and audits; (b) issue warnings and orders; (c) impose administrative fines; (d) order the suspension or cessation of processing; (e) require the controller to notify data subjects of a breach."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-36", "depth": 3, "ref_id": "IR-Art-36", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:supervisory-authority-and-enforcement", "description": "Any data subject may lodge a complaint with the competent authority regarding an alleged infringement of this Law. The competent authority shall investigate the complaint and inform the complainant of the outcome within the period specified in this Regulation."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-37", "depth": 3, "ref_id": "IR-Art-37", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:supervisory-authority-and-enforcement", "description": "The competent authority shall maintain public registers and databases as necessary for the effective implementation of this Law, including the register of controllers and processors and the register of approved certifications."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:ir-art-38", "depth": 3, "ref_id": "IR-Art-38", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:supervisory-authority-and-enforcement", "description": "This Regulation shall be published in the Official Gazette and shall come into force on the date of its publication or on the date specified therein."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:regulation-on-personal-data-transfer-outside-the-kingdom", "name": "Regulation on Personal Data Transfer Outside the Kingdom", "depth": 1, "assessable": false}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:definitions-and-general-provisions", "name": "Definitions and General Provisions", "depth": 2, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:regulation-on-personal-data-transfer-outside-the-kingdom"}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:tr-art-1", "depth": 3, "ref_id": "TR-Art-1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:definitions-and-general-provisions", "description": "This Regulation specifies the rules and conditions governing the transfer of personal data outside the Kingdom of Saudi Arabia. It defines the terms and expressions used in this Regulation, supplementing the definitions in the Personal Data Protection Law and its Implementing Regulation."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:tr-art-2", "depth": 3, "ref_id": "TR-Art-2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:definitions-and-general-provisions", "description": "Personal data shall not be transferred outside the Kingdom unless the transfer is carried out in accordance with the provisions of this Regulation and the requirements of the Personal Data Protection Law. The controller shall be responsible for ensuring compliance with all conditions for transfer and shall be able to demonstrate such compliance."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:transfer-based-on-adequate-level-of-protection", "name": "Transfer Based on Adequate Level of Protection", "depth": 2, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:regulation-on-personal-data-transfer-outside-the-kingdom"}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:tr-art-3", "depth": 3, "ref_id": "TR-Art-3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:transfer-based-on-adequate-level-of-protection", "description": "The competent authority shall assess and publish a list of countries and international organizations that provide an adequate level of protection for personal data. The assessment shall take into account: (a) the rule of law; (b) the existence and effectiveness of data protection legislation; (c) the existence of an independent supervisory authority; (d) international commitments; (e) the security situation in the receiving country."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:tr-art-4", "depth": 3, "ref_id": "TR-Art-4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:transfer-based-on-adequate-level-of-protection", "description": "Where the receiving country or international organization has been determined to provide an adequate level of protection, personal data may be transferred without the need for additional safeguards. The adequacy determination shall be reviewed periodically by the competent authority and may be amended or revoked."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:transfer-based-on-appropriate-safeguards-and-exemptions", "name": "Transfer Based on Appropriate Safeguards and Exemptions", "depth": 2, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:regulation-on-personal-data-transfer-outside-the-kingdom"}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:tr-art-5", "depth": 3, "ref_id": "TR-Art-5", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:transfer-based-on-appropriate-safeguards-and-exemptions", "description": "In the absence of an adequacy determination, the controller may transfer personal data outside the Kingdom subject to appropriate safeguards, including: (a) binding corporate rules approved by the competent authority; (b) standard contractual clauses issued or approved by the competent authority; (c) an approved code of conduct together with binding commitments; (d) an approved certification mechanism."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:tr-art-6", "depth": 3, "ref_id": "TR-Art-6", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:transfer-based-on-appropriate-safeguards-and-exemptions", "description": "Personal data may be transferred outside the Kingdom in the following cases, notwithstanding the absence of an adequacy determination or appropriate safeguards: (a) explicit consent of the data subject after being informed of the risks; (b) performance of a contract between the data subject and controller; (c) important reasons of public interest; (d) establishment, exercise or defense of legal claims; (e) protection of vital interests of the data subject."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:tr-art-7", "depth": 3, "ref_id": "TR-Art-7", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:transfer-based-on-appropriate-safeguards-and-exemptions", "description": "The controller shall conduct a transfer impact assessment before transferring personal data outside the Kingdom in the absence of an adequacy determination. The assessment shall evaluate the level of protection in the receiving country and identify supplementary measures necessary to ensure an essentially equivalent level of protection."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:final-provisions-on-data-transfer", "name": "Final Provisions on Data Transfer", "depth": 2, "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:regulation-on-personal-data-transfer-outside-the-kingdom"}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:tr-art-8", "depth": 3, "ref_id": "TR-Art-8", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:final-provisions-on-data-transfer", "description": "The competent authority may restrict or prohibit the transfer of specific categories of personal data outside the Kingdom where such transfer would jeopardize national security, the vital interests of the Kingdom, or the rights of data subjects. Such restrictions shall be published."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:tr-art-9", "depth": 3, "ref_id": "TR-Art-9", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:final-provisions-on-data-transfer", "description": "The controller shall maintain records of all cross-border transfers of personal data, including: (a) the identity of the recipient; (b) the country of destination; (c) the legal basis for the transfer; (d) the categories and volume of data transferred; (e) the safeguards in place; (f) the date of transfer."}, {"urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:tr-art-10", "depth": 3, "ref_id": "TR-Art-10", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:saudi-pdpl-1.0:final-provisions-on-data-transfer", "description": "This Regulation shall be published in the Official Gazette and shall come into force on the date of its publication or on the date specified therein. Entities shall adjust their status in accordance with the provisions of this Regulation within the period specified by the competent authority."}]}}	f
5a5d8e18-fcc4-4732-85a1-bd72aab5f158	2026-04-05 13:50:46.964785+00	2026-04-05 17:11:10.836407+00	f	urn:intuitem:risk:library:qyias-5	qyias-digital-transformation-standards	DGA	المعايير الأساسية للتحول الرقمي - Qyias Digital Transformation Standards	المعايير الأساسية للتحول الرقمي الصادرة عن هيئة الحكومة الرقمية (DGA) - الإصدار 3.0 بتاريخ 19 مارس 2024. رقم الوثيقة: DGA-1-2-1-111. تتضمن 10 منظورات و23 محوراً و96 معياراً لقياس التحول الرقمي في الجهات الحكومية السعودية.\r\nQyias Digital Transformation Standards issued by Digital Government Authority (DGA) - Version 3.0, March 19, 2024. Document ID: DGA-1-2-1-111. Contains 10 perspectives, 23 axes, and 96 standards for measuring digital transformation in Saudi government entities.	\N	\N	ar	t	© هيئة الحكومة الرقمية - Digital Government Authority (DGA)	1	wathba	2025-01-01	f	{"framework": 1, "requirement_node": 661}	\N	f	2c48279732ae88572c0f91835fcdd457772104c4964241aa6488ae4b496adacc	{"framework": {"tab": "qyias", "urn": "urn:intuitem:risk:framework:qyias-5", "name": "المعايير الأساسية للتحول الرقمي (قياس)", "ref_id": "qyias-digital-transformation-standards", "description": "إطار قياس التحول الرقمي للجهات الحكومية السعودية - Digital Transformation Measurement Framework for Saudi Government Entities", "requirement_nodes": [{"urn": "urn:intuitem:risk:req_node:qyias-5:p1", "name": "الاستراتيجية والتخطيط", "depth": 1, "ref_id": "P1", "assessable": false}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1", "name": "التخطيط للتحول الرقمي", "depth": 2, "ref_id": "5.1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:qyias-5:p1"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1", "name": "التخطيط الاستراتيجي للتحول الرقمي", "depth": 3, "ref_id": "5.1.1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:qyias-5:5.1", "description": "تطوير خطة استراتيجية للتحول الرقمي متوائمة مع استراتيجية الجهة ومستهدفات رؤية المملكة 2030."}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.1", "depth": 4, "ref_id": "5.1.1.1", "questions": {"urn:intuitem:risk:req_node:qyias-5:5.1.1.1:question:1": {"text": "هل توجد وثيقة استراتيجية رسمية للتحول الرقمي أو للتعاملات الإلكترونية الحكومية معتمدة من القيادة العليا للجهة؟", "type": "unique_choice", "choices": [{"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.1:question:1:choice:1", "value": "Yes"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.1:question:1:choice:2", "value": "No"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.1:question:1:choice:3", "value": "Partial"}]}, "urn:intuitem:risk:req_node:qyias-5:5.1.1.1:question:2": {"text": "كيف تضمن استراتيجية التحول الرقمي الخاصة بكم اشتمالها على رؤية واضحة، رسالة محددة، ركائز أساسية وأهداف استراتيجية قابلة للقياس؟", "type": "unique_choice", "choices": [{"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.1:question:2:choice:1", "value": "Yes"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.1:question:2:choice:2", "value": "No"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.1:question:2:choice:3", "value": "Partial"}]}, "urn:intuitem:risk:req_node:qyias-5:5.1.1.1:question:3": {"text": "ما هي الآليات المتبعة لربط أهداف ومبادرات استراتيجية التحول الرقمي مع الاستراتيجية العامة للجهة لضمان التوافق؟", "type": "unique_choice", "choices": [{"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.1:question:3:choice:1", "value": "Yes"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.1:question:3:choice:2", "value": "No"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.1:question:3:choice:3", "value": "Partial"}]}, "urn:intuitem:risk:req_node:qyias-5:5.1.1.1:question:4": {"text": "هل تم إشراك أصحاب المصلحة الرئيسيين داخل وخارج الجهة في عملية إعداد وتطوير استراتيجية التحول الرقمي؟", "type": "unique_choice", "choices": [{"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.1:question:4:choice:1", "value": "Yes"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.1:question:4:choice:2", "value": "No"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.1:question:4:choice:3", "value": "Partial"}]}, "urn:intuitem:risk:req_node:qyias-5:5.1.1.1:question:5": {"text": "ما هي العملية المتبعة لمراجعة وتحديث استراتيجية التحول الرقمي بشكل دوري لضمان استمراريتها وملاءمتها للتغيرات؟", "type": "unique_choice", "choices": [{"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.1:question:5:choice:1", "value": "Yes"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.1:question:5:choice:2", "value": "No"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.1:question:5:choice:3", "value": "Partial"}]}}, "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1", "description": "إعداد استراتيجية للتحول الرقمي/ للتحول للتعاملات الإلكترونية الحكومية بحيث تشمل رؤية ورسالة وركائز وأهداف استراتيجية وربطها باستراتيجية الجهة", "typical_evidence": "- وثيقة استراتيجية التحول الرقمي المعتمدة للجهة: وثيقة رسمية معتمدة تحدد رؤية ورسالة وأهداف وركائز التحول الرقمي للجهة، ويجب أن تكون موقعة من القيادة العليا ومؤرخة بشكل واضح.\\n- محاضر اجتماعات اعتماد استراتيجية التحول الرقمي: محاضر اجتماعات مجالس الإدارة أو اللجان العليا التي تمت فيها مناقشة واعتماد استراتيجية التحول الرقمي، موثقة بالتواريخ والحضور والقرارات المتخذة.\\n- مصفوفة ربط استراتيجية التحول الرقمي بالاستراتيجية العامة: وثيقة توضح كيفية ربط أهداف ومبادرات استراتيجية التحول الرقمي بالأهداف الاستراتيجية الشاملة للجهة، لتأكيد التوافق والانسجام التام بينهما.\\n- خطة نشر وتعميم استراتيجية التحول الرقمي: خطة تفصيلية توضح قنوات وأساليب وتوقيتات نشر استراتيجية التحول الرقمي على جميع المستويات داخل الجهة لضمان فهمها وتبنيها من قبل الموظفين.\\n- مؤشرات الأداء الرئيسية (KPIs) لأهداف الاستراتيجية الرقمية: وثيقة تحتوي على مؤشرات أداء قابلة للقياس الكمي والنوعي لتقييم مدى تحقيق أهداف استراتيجية التحول الرقمي، مع تحديد المسؤوليات والجداول الزمنية المحددة."}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.2", "depth": 4, "ref_id": "5.1.1.2", "questions": {"urn:intuitem:risk:req_node:qyias-5:5.1.1.2:question:1": {"text": "هل تم إعداد وثيقة استراتيجية للتحول الرقمي/للتعاملات الإلكترونية الحكومية بشكل رسمي ومعتمد من القيادة العليا للمؤسسة؟", "type": "unique_choice", "choices": [{"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.2:question:1:choice:1", "value": "Yes"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.2:question:1:choice:2", "value": "No"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.2:question:1:choice:3", "value": "Partial"}]}, "urn:intuitem:risk:req_node:qyias-5:5.1.1.2:question:2": {"text": "ما هي المبادرات والمشاريع الاستراتيجية الرئيسية التي تم تحديدها ضمن هذه الاستراتيجية وكيف ترتبط بالأهداف العامة للتحول الرقمي؟", "type": "unique_choice", "choices": [{"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.2:question:2:choice:1", "value": "Yes"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.2:question:2:choice:2", "value": "No"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.2:question:2:choice:3", "value": "Partial"}]}, "urn:intuitem:risk:req_node:qyias-5:5.1.1.2:question:3": {"text": "كيف تم تحديد مؤشرات الأداء الاستراتيجية (KPIs) لقياس التقدم المحرز في تنفيذ الاستراتيجية، وما هي آلية متابعتها والإبلاغ عنها؟", "type": "unique_choice", "choices": [{"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.2:question:3:choice:1", "value": "Yes"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.2:question:3:choice:2", "value": "No"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.2:question:3:choice:3", "value": "Partial"}]}, "urn:intuitem:risk:req_node:qyias-5:5.1.1.2:question:4": {"text": "هل تم تخصيص الموارد اللازمة (البشرية، المالية، التقنية) لدعم تنفيذ المبادرات والمشاريع الاستراتيجية المذكورة في الاستراتيجية؟", "type": "unique_choice", "choices": [{"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.2:question:4:choice:1", "value": "Yes"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.2:question:4:choice:2", "value": "No"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.2:question:4:choice:3", "value": "Partial"}]}, "urn:intuitem:risk:req_node:qyias-5:5.1.1.2:question:5": {"text": "ما هي عملية المراجعة والتحديث الدورية المتبعة لاستراتيجية التحول الرقمي لضمان بقائها ملائمة ومتماشية مع التغيرات والتطورات؟", "type": "unique_choice", "choices": [{"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.2:question:5:choice:1", "value": "Yes"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.2:question:5:choice:2", "value": "No"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.2:question:5:choice:3", "value": "Partial"}]}}, "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1", "description": "إعداد استراتيجية للتحول الرقمي/ للتحول للتعاملات الإلكترونية الحكومية بحيث تشمل المبادرات والمشاريع الاستراتيجية ومؤشرات الأداء الاستراتيجية", "typical_evidence": "- وثيقة استراتيجية التحول الرقمي المعتمدة رسمياً: يجب أن تتضمن الوثيقة الرسمية لاستراتيجية التحول الرقمي رؤية واضحة، أهدافًا محددة، المبادرات والمشاريع الاستراتيجية، ومؤشرات الأداء الرئيسية لقياس التقدم المحرز بشكل دوري ومستمر مع تحديد آليات التنفيذ.\\n- محاضر اجتماعات اللجان العليا للموافقة على الاستراتيجية: توثيق محاضر اجتماعات اللجان العليا أو مجالس الإدارة التي ناقشت ووافقت على استراتيجية التحول الرقمي، مما يثبت الالتزام الرسمي من القيادة العليا وتخصيص الموارد اللازمة لتنفيذها بفعالية وكفاءة عالية.\\n- خطة عمل تفصيلية للمبادرات والمشاريع الاستراتيجية المحددة: وثيقة تفصيلية لكل مبادرة ومشروع استراتيجي ضمن الاستراتيجية، تتضمن الجداول الزمنية، الموارد المخصصة، المسؤوليات، والمخرجات المحددة بوضوح، لضمان التنفيذ المنظم والفعال للمشاريع ضمن الإطار الزمني والميزانية المحددة.\\n- إطار عمل مؤشرات الأداء الاستراتيجية ولوحات المتابعة: وثيقة تحدد مؤشرات الأداء الرئيسية (KPIs) لكل هدف استراتيجي، مع تعريف واضح لكل مؤشر، منهجية القياس، وتواتر التقارير، بالإضافة إلى لوحات متابعة تعرض الأداء الحالي مقابل الأهداف المحددة والمستهدفة.\\n- خطة الاتصال والتوعية الشاملة باستراتيجية التحول الرقمي: خطة توضح كيفية نشر الوعي بالاستراتيجية وأهدافها بين جميع أصحاب المصلحة الداخليين والخارجيين، بما في ذلك ورش العمل، المواد التوعوية، والاجتماعات الدورية، لضمان الفهم والالتزام المشترك وتحقيق المشاركة الفعالة."}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.3", "depth": 4, "ref_id": "5.1.1.3", "questions": {"urn:intuitem:risk:req_node:qyias-5:5.1.1.3:question:1": {"text": "هل تتضمن استراتيجية التحول الرقمي الخاصة بكم نموذجًا تفصيليًا لتحقيق التكامل مع الجهات الخارجية ذات العلاقة؟", "type": "unique_choice", "choices": [{"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.3:question:1:choice:1", "value": "Yes"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.3:question:1:choice:2", "value": "No"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.3:question:1:choice:3", "value": "Partial"}]}, "urn:intuitem:risk:req_node:qyias-5:5.1.1.3:question:2": {"text": "ما هي الآليات المحددة التي تتبعونها لضمان التوافق التقني والتشغيلي مع أنظمة الجهات الخارجية عند تنفيذ مبادرات التكامل؟", "type": "unique_choice", "choices": [{"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.3:question:2:choice:1", "value": "Yes"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.3:question:2:choice:2", "value": "No"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.3:question:2:choice:3", "value": "Partial"}]}, "urn:intuitem:risk:req_node:qyias-5:5.1.1.3:question:3": {"text": "كيف يتم تحديد الجهات الخارجية ذات العلاقة التي يجب التكامل معها، وما هي المعايير المعتمدة لهذا الاختيار؟", "type": "unique_choice", "choices": [{"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.3:question:3:choice:1", "value": "Yes"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.3:question:3:choice:2", "value": "No"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.3:question:3:choice:3", "value": "Partial"}]}, "urn:intuitem:risk:req_node:qyias-5:5.1.1.3:question:4": {"text": "ما هي مؤشرات الأداء الرئيسية (KPIs) التي تستخدمونها لقياس نجاح وفعالية عمليات التكامل مع الجهات الخارجية؟", "type": "unique_choice", "choices": [{"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.3:question:4:choice:1", "value": "Yes"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.3:question:4:choice:2", "value": "No"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.3:question:4:choice:3", "value": "Partial"}]}, "urn:intuitem:risk:req_node:qyias-5:5.1.1.3:question:5": {"text": "هل تم تخصيص موارد كافية، بما في ذلك الميزانية والكوادر البشرية المتخصصة، لدعم وتنفيذ مشاريع التكامل مع الجهات الخارجية؟", "type": "unique_choice", "choices": [{"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.3:question:5:choice:1", "value": "Yes"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.3:question:5:choice:2", "value": "No"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.3:question:5:choice:3", "value": "Partial"}]}}, "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1", "description": "إعداد استراتيجية للتحول الرقمي/ للتحول للتعاملات الإلكترونية الحكومية بحيث تشمل نموذج تحقيق التكامل مع الجهات الخاراية ذات العلاقة لتحقيق المستهدفات", "typical_evidence": "- وثيقة استراتيجية التحول الرقمي الشاملة المعتمدة: تتضمن هذه الوثيقة الرسمية المعتمدة من الإدارة العليا الرؤية والأهداف والمبادرات الرئيسية للتحول الرقمي، ويجب أن تتضمن بوضوح قسمًا مخصصًا لكيفية تحقيق التكامل مع الجهات الخارجية ذات الصلة لتحقيق الأهداف الاستراتيجية المشتركة.\\n- نموذج أو إطار عمل التكامل مع الجهات الخارجية: مستند تفصيلي يحدد الأطر التقنية والتشغيلية والحوكمية اللازمة لتمكين التكامل الفعال والآمن مع الشركاء والجهات الحكومية الأخرى، بما يضمن تبادل البيانات والخدمات بسلاسة ووفقًا للمعايير والسياسات المعتمدة.\\n- محاضر اجتماعات وورش عمل مشتركة مع الشركاء: سجلات رسمية لاجتماعات وورش العمل التي عقدت مع الجهات الخارجية ذات الصلة لمناقشة متطلبات التكامل، وتحديد المسؤوليات، ووضع خطط العمل المشتركة، وإظهار التزام الطرفين بتحقيق الأهداف المشتركة والتعاون المستمر.\\n- مؤشرات الأداء الرئيسية وتقارير قياس التكامل: وثيقة تحدد مؤشرات الأداء الرئيسية (KPIs) التي تستخدم لقياس فعالية وكفاءة عمليات التكامل مع الجهات الخارجية، بالإضافة إلى تقارير دورية تظهر مدى التقدم المحرز نحو تحقيق الأهداف المحددة للتكامل وفعاليته.\\n- سجل مخاطر التكامل الخارجي وإجراءات التخفيف: سجل يوثق المخاطر المحتملة المرتبطة بعمليات التكامل مع الجهات الخارجية، مثل مخاطر الأمن السيبراني أو تحديات التوافق التقني أو التشغيلي، ويصف الإجراءات المتخذة للتخفيف من هذه المخاطر ومعالجتها بفعالية لضمان استمرارية الخدمات."}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.4", "depth": 4, "ref_id": "5.1.1.4", "questions": {"urn:intuitem:risk:req_node:qyias-5:5.1.1.4:question:1": {"text": "كيف تم تطوير واعتماد استراتيجية التحول الرقمي لجهتكم، وما هي الآلية المتبعة لضمان اشتمالها على الجدارات والمهارات اللازمة؟", "type": "unique_choice", "choices": [{"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.4:question:1:choice:1", "value": "Yes"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.4:question:1:choice:2", "value": "No"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.4:question:1:choice:3", "value": "Partial"}]}, "urn:intuitem:risk:req_node:qyias-5:5.1.1.4:question:2": {"text": "ما هي المنهجية التي اتبعتموها لتحديد الجدارات والمهارات الرقمية المطلوبة لتحقيق مستهدفات خطتكم للتعاملات الإلكترونية الحكومية؟", "type": "unique_choice", "choices": [{"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.4:question:2:choice:1", "value": "Yes"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.4:question:2:choice:2", "value": "No"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.4:question:2:choice:3", "value": "Partial"}]}, "urn:intuitem:risk:req_node:qyias-5:5.1.1.4:question:3": {"text": "هل توجد خطة تنفيذية مفصلة لسد أي فجوات في الجدارات والمهارات الرقمية المحددة، وما هي مؤشرات الأداء الرئيسية لقياس فعاليتها؟", "type": "unique_choice", "choices": [{"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.4:question:3:choice:1", "value": "Yes"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.4:question:3:choice:2", "value": "No"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.4:question:3:choice:3", "value": "Partial"}]}, "urn:intuitem:risk:req_node:qyias-5:5.1.1.4:question:4": {"text": "كيف يتم ربط الجدارات والمهارات الرقمية المحددة في الاستراتيجية بعمليات التوظيف والتدريب وتقييم الأداء الحالية في الجهة؟", "type": "unique_choice", "choices": [{"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.4:question:4:choice:1", "value": "Yes"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.4:question:4:choice:2", "value": "No"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.4:question:4:choice:3", "value": "Partial"}]}, "urn:intuitem:risk:req_node:qyias-5:5.1.1.4:question:5": {"text": "متى تم آخر مراجعة وتحديث لاستراتيجية التحول الرقمي، وكيف يتم ضمان مواكبتها للتغيرات المتسارعة في التقنيات والجدارات الرقمية المطلوبة؟", "type": "unique_choice", "choices": [{"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.4:question:5:choice:1", "value": "Yes"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.4:question:5:choice:2", "value": "No"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1.4:question:5:choice:3", "value": "Partial"}]}}, "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:qyias-5:5.1.1", "description": "إعداد استراتيجية للتحول الرقمي/ للتحول للتعاملات الإلكترونية الحكومية بحيث تشمل الجدارات والمهارات اللازمة لتحقيق مستهدفات الخطة", "typical_evidence": "- وثيقة استراتيجية التحول الرقمي المعتمدة والمنشورة: وثيقة الاستراتيجية الرسمية والمعتمدة للتحول الرقمي للجهة، والتي يجب أن تتضمن بوضوح الأهداف، المبادرات، والجدارات والمهارات المطلوبة لتحقيق هذه الأهداف، بالإضافة إلى خطة زمنية ومؤشرات أداء رئيسية مفصلة.\\n- تقرير تحليل فجوة الجدارات والمهارات الرقمية: تقرير مفصل يوضح الفجوة الحالية بين الجدارات والمهارات المتوفرة لدى موظفي الجهة وتلك المطلوبة لتحقيق أهداف استراتيجية التحول الرقمي، مع توصيات واضحة ومحددة لسد هذه الفجوات بشكل فعال.\\n- خطة تطوير الجدارات والمهارات الرقمية للموظفين: خطة عمل مفصلة تتضمن البرامج التدريبية وورش العمل ومسارات التطوير المهني المخصصة لبناء وتعزيز الجدارات والمهارات الرقمية اللازمة لموظفي الجهة، بما يتماشى مع أهداف الاستراتيجية المعتمدة للتحول الرقمي.\\n- محاضر اجتماعات لجنة التوجيه للتحول الرقمي: محاضر الاجتماعات الرسمية للجنة التوجيه أو الإدارة العليا التي ناقشت ووافقت على استراتيجية التحول الرقمي، بما في ذلك المكونات المتعلقة بالجدارات والمهارات، ومتابعة تنفيذها وتقييم التقدم المحرز فيها بانتظام.\\n- مصفوفة الجدارات والمهارات الرقمية للمناصب الرئيسية: مصفوفة تحدد الجدارات والمهارات الرقمية الأساسية والمتقدمة المطلوبة لكل منصب وظيفي رئيسي داخل الجهة، وكيفية ربطها بمسارات التطور الوظيفي وتقييم الأداء لضمان المواءمة المستمرة مع متطلبات الاستراتيجية."}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.2", "name": "التخطيط التنفيذي للتحول الرقمي", "depth": 3, "ref_id": "5.1.2", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:qyias-5:5.1", "description": "تطوير خطة تنفيذية للتحول الرقمي وفق أفضل الممارسات معتمدة على الخطة الاستراتيجية للتحول الرقمي للجهة وتحدد الآليات والجداول الزمنية للتنفيذ والمتابعة."}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.2.1", "depth": 4, "ref_id": "5.1.2.1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:qyias-5:5.1.2", "description": "إعداد خطة تنفيذية للتحوّل الرقمي/ للتحول للتعاملات الإلكترونية الحكومية مبنية على الخطة الاستراتيجية بحيث تشمل حصر تفصيلي للمبادرات والمشاريع الخاصة بالتحول الرقمي"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.2.2", "depth": 4, "ref_id": "5.1.2.2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:qyias-5:5.1.2", "description": "إعداد خطة تنفيذية للتحوّل الرقمي/ للتحول للتعاملات الإلكترونية الحكومية مبنية على الخطة الاستراتيجية بحيث تشمل تحديد الجدول الزمني لتنفيذ هذه المبادرات والمشاريع ومراحل التنفيذ"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.2.3", "depth": 4, "ref_id": "5.1.2.3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:qyias-5:5.1.2", "description": "إعداد خطة تنفيذية للتحوّل الرقمي/ للتحول للتعاملات الإلكترونية الحكومية مبنية على الخطة الاستراتيجية بحيث تشمل وضع أهداف مرحلية (تنفيذية)"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.2.4", "depth": 4, "ref_id": "5.1.2.4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:qyias-5:5.1.2", "description": "إعداد خطة تنفيذية للتحوّل الرقمي/ للتحول للتعاملات الإلكترونية الحكومية مبنية على الخطة الاستراتيجية بحيث تشمل تحديد مؤشرات الأداء للخطة للتنفيذية"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.3", "name": "تأسيس وحدة لإدارة مشاريع التحول الرقمي", "depth": 3, "ref_id": "5.1.3", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:qyias-5:5.1", "description": "إنشاء وحدة لإدارة مشاريع التحول الرقمي لتحقيق كفاءة المشاريع الرقمية ومتابعة التقدم في التحول الرقمي."}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.3.1", "depth": 4, "ref_id": "5.1.3.1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:qyias-5:5.1.3", "description": "إنشاء وحدة لإدارة مشاريع التحول الرقمي في الجهة"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.3.2", "depth": 4, "ref_id": "5.1.3.2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:qyias-5:5.1.3", "description": "وجود هيكلية واضحة لوحدة إدارة مشاريع التحول الرقمي وحدود الصلاحيات والمسؤوليات"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.1.3.3", "depth": 4, "ref_id": "5.1.3.3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:qyias-5:5.1.3", "description": "متابعة مدى التقدم في التحول الرقمي/ التحول للتعاملات الإلكترونية بشكل دوري وتضمين النتائج ضمن التقرير السنوي للجهة."}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.2", "name": "حوكمة التحول الرقمي", "depth": 2, "ref_id": "5.2", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:qyias-5:p1"}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.2.1", "name": "اعتماد إطار لحوكمة التحول الرقمي", "depth": 3, "ref_id": "5.2.1", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:qyias-5:5.2", "description": "وضع إطار عام لحوكمة التحول الرقمي يهدف إلى متابعة تنفيذ خطط التحول الرقمي وضمان تحقيق المستهدفات."}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.2.1.1", "depth": 4, "ref_id": "5.2.1.1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:qyias-5:5.2.1", "description": "وضع إطار لحوكمة التحول الرقمي يغطي كافة المبادرات والعمليات المتعلقة بالتحول الرقمي ."}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.2.1.2", "depth": 4, "ref_id": "5.2.1.2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:qyias-5:5.2.1", "description": "تحديد آلية المتابعة والقياس، ونماذج التقارير الدورية والتي سيتم من خلالها قياس التقدم في عمليات تنفيذ مبادرات ومشاريع التحول الرقمي."}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.2.1.3", "depth": 4, "ref_id": "5.2.1.3", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:qyias-5:5.2.1", "description": "تحديد الإدارات واللجان المسؤولة عن عمليات الحوكمة وعمليات التغيير، بما في ذلك حوكمة وإدارة المنتجات والخدمات المشتركة."}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.2.1.4", "depth": 4, "ref_id": "5.2.1.4", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:qyias-5:5.2.1", "description": "توحيد الإدارات المشرفة على تقنية المعلومات تحت إدارة عامة بمسمى الإدارة العامة لتقنية المعلومات ومرتبطة بالمسؤول الأول أو من ينيبه، وتخصيص منصب مدير عام يراعى فيه التأهيل المناسب."}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.2.1.5", "depth": 4, "ref_id": "5.2.1.5", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:qyias-5:5.2.1", "description": "تكوين لجنة التعاملات الإلكترونية/ ا لتحول الرقمي برئاسة المسؤول الأول بالجهة أو من ينيبه وعضوية الإدارات/ الوكالات ذات العلاقة."}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.2.2", "name": "تطبيق إطار لحوكمة التحول الرقمي", "depth": 3, "ref_id": "5.2.2", "assessable": false, "parent_urn": "urn:intuitem:risk:req_node:qyias-5:5.2", "description": "تنفيذ إطار حوكمة التحول الرقمي ومراقبة التقدم في عمليات التنفيذ واتخاذ الإجراءات التصحيحية اللازمة."}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.2.2.1", "depth": 4, "ref_id": "5.2.2.1", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:qyias-5:5.2.2", "description": "وضع بطاقة لكل مبادرة من مبادرات التحول الرقمي."}, {"urn": "urn:intuitem:risk:req_node:qyias-5:5.2.2.2", "depth": 4, "ref_id": "5.2.2.2", "assessable": true, "parent_urn": "urn:intuitem:risk:req_node:qyias-5:5.2.2", "description": "إصدار تقارير الأداء الدورية لمبادرات ومشاريع التحول الرقمي توضح نسبة الإنجاز في مراحل التنفيذ"}, {